                          max={targetPlan?.limits.maxUsers === -1 ? 500 : targetPlan?.limits.maxUsers || 100}
                          value={seats}
                          onChange={(e) => handleSeatChange(parseInt(e.target.value) || Math.max(currentActiveUsers, 1))}
                          aria-label="Number of seats"
                          className="h-8 text-center text-sm font-bold w-16 border-0 focus-visible:ring-0"
                        />
                        <Button
                          type="button"
                          variant="ghost"
                          size="icon"
                          onClick={() => handleSeatChange(seats + 1)}
                          aria-label="Increase seat count"
                          className="h-8 w-8 rounded-lg cursor-pointer"
                        >
                          <Plus className="w-3.5 h-3.5" />
                        </Button>
                      </div>
                      <span className="text-xs text-muted-foreground font-medium">
                        seats × {targetPlan?.price}/user/month
                      </span>
                    </div>
                  </div>

                  {/* Billing Cycle Toggle in Modal */}
                  <div className="space-y-1.5">
                    <Label className="text-xs font-bold">Billing Cycle</Label>
                    <div className="grid grid-cols-2 gap-2">
                      <button
                        type="button"
                        onClick={() => handleCycleChangeInModal("monthly")}
                        className={`p-3 rounded-xl border text-left text-xs transition-all cursor-pointer ${
                          billingCycle === "monthly"
                            ? "border-primary bg-primary/5 text-foreground ring-1 ring-primary"
                            : "border-border hover:bg-muted text-muted-foreground"
                        }`}
                      >
                        <div className="font-bold">Monthly Billing</div>
                        <div className="text-[11px] text-muted-foreground mt-0.5">Billed every month</div>
                      </button>

                      <button
                        type="button"
                        onClick={() => handleCycleChangeInModal("annual")}
                        className={`p-3 rounded-xl border text-left text-xs transition-all cursor-pointer ${
                          billingCycle === "annual"
                            ? "border-primary bg-primary/5 text-foreground ring-1 ring-primary"
                            : "border-border hover:bg-muted text-muted-foreground"
                        }`}
                      >
                        <div className="font-bold flex items-center justify-between">
                          <span>Annual Billing</span>
                          <span className="text-[9.5px] px-1.5 py-0.5 rounded bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 font-extrabold">
                            Save ~17%
                          </span>
                        </div>
                        <div className="text-[11px] text-muted-foreground mt-0.5">Billed yearly</div>
                      </button>
                    </div>
                  </div>

                  {/* Live Quote Breakdown */}
                  {currentQuote && (
                    <div className="p-4 rounded-xl bg-muted/40 border border-border/80 space-y-2 text-xs">
                      <div className="text-[11px] font-extrabold uppercase tracking-wider text-muted-foreground mb-1">
                        Billing Calculation Summary
                      </div>

                      <div className="flex justify-between">
                        <span className="text-muted-foreground">
                          {targetPlan?.name} ({seats} seats × ₹{currentQuote.unitPricePerMonth}/mo)
                        </span>
                        <span className="font-semibold text-foreground">
                          ₹{currentQuote.unitPricePerMonth * seats * (billingCycle === "annual" ? 12 : 1)}
                        </span>
                      </div>

                      {billingCycle === "annual" && currentQuote.annualDiscountAmount > 0 && (
                        <div className="flex justify-between text-emerald-600 dark:text-emerald-400 font-medium">
                          <span>Annual Savings (~17% discount)</span>
                          <span>-₹{currentQuote.annualDiscountAmount.toLocaleString("en-IN")}</span>
                        </div>
                      )}

                      <div className="flex justify-between">
                        <span className="text-muted-foreground">Subtotal ({currentQuote.intervalDescription})</span>
                        <span className="font-semibold text-foreground">
                          ₹{currentQuote.subtotal.toLocaleString("en-IN")}
                        </span>
                      </div>

                      {currentQuote.taxAmount > 0 && (
                        <div className="flex justify-between text-muted-foreground">
                          <span>Estimated GST (18%)</span>
                          <span>₹{currentQuote.taxAmount.toLocaleString("en-IN")}</span>
                        </div>
                      )}

                      <div className="pt-2.5 border-t border-border/60 flex justify-between items-baseline font-bold text-sm">
                        <span className="text-foreground">Total Recurring Amount:</span>
                        <span className="text-primary text-base font-black">
                          ₹{currentQuote.totalAmount.toLocaleString("en-IN")}
                          <span className="text-xs font-normal text-muted-foreground ml-1">
                            /{billingCycle === "annual" ? "yr" : "mo"}
                          </span>
                        </span>
                      </div>
                    </div>
                  )}
                </div>

                <DialogFooter className="gap-2 sm:gap-0 pt-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setUpgradeModalOpen(false)}
                    className="text-xs rounded-xl"
                  >
                    Cancel
                  </Button>
                  <Button
                    size="sm"
                    onClick={handleExecuteUpgrade}
                    disabled={isProcessingCheckout || isVerifyingPayment || isChangingPlan}
                    className="bg-primary text-primary-foreground text-xs font-bold gap-1.5 shadow-xs rounded-xl cursor-pointer"
                  >
                    {isProcessingCheckout || isVerifyingPayment || isChangingPlan
                      ? "Processing Checkout..."
                      : "Proceed to Checkout"}
                    <ArrowRight className="w-3.5 h-3.5" />
                  </Button>
                </DialogFooter>
              </div>
            ) : (
              /* SUCCESS STATE */
              <div className="py-6 text-center space-y-4">
                <div className="w-14 h-14 rounded-2xl bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20 flex items-center justify-center mx-auto shadow-xs">
                  <CheckCircle2 className="w-8 h-8" />
                </div>

                <div className="space-y-1.5">
                  <h3 className="text-xl font-extrabold text-foreground">
                    You&apos;re now on {targetPlan?.name}!
                  </h3>
                  <p className="text-xs text-muted-foreground max-w-sm mx-auto leading-relaxed">
                    Your workspace subscription has been upgraded successfully. New limits and features are active immediately.
                  </p>
                </div>

                <div className="p-3.5 rounded-xl bg-muted/40 border border-border/80 max-w-xs mx-auto text-xs text-left space-y-1.5">
                  <div className="flex justify-between">
                    <span className="text-muted-foreground">Active Plan:</span>
                    <span className="font-bold text-foreground">{targetPlan?.name}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-muted-foreground">Allocated Seats:</span>
                    <span className="font-bold text-foreground">{seats} users</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-muted-foreground">Billing Interval:</span>
                    <span className="font-bold text-foreground capitalize">{billingCycle}</span>
                  </div>
                </div>

                <div className="pt-2">
                  <Button
                    onClick={() => {
                      setUpgradeModalOpen(false);
                      router.push("/dashboard");
                    }}
                    className="bg-primary text-primary-foreground text-xs font-bold px-8 shadow-xs rounded-xl cursor-pointer"
                  >
                    Go to CRM Dashboard
                  </Button>
                </div>
              </div>
            )}
          </DialogContent>
        </Dialog>

        {/* ENTERPRISE CONTACT SALES MODAL */}
        <Dialog open={enterpriseModalOpen} onOpenChange={setEnterpriseModalOpen}>
          <DialogContent className="sm:max-w-lg rounded-2xl">
            <form onSubmit={handleEnterpriseInquirySubmit} className="space-y-4">
              <DialogHeader>
                <div className="flex items-center gap-3 mb-1">
                  <div className="p-2.5 rounded-xl bg-amber-500/10 text-amber-600 dark:text-amber-400 border border-amber-500/20 shrink-0">
                    <Crown className="w-5 h-5" />
                  </div>
                  <div>
                    <DialogTitle className="text-base sm:text-lg font-bold">
                      Contact Enterprise Sales
                    </DialogTitle>
                    <DialogDescription className="text-xs text-muted-foreground">
                      Custom seat allocations, SAML 2.0 SSO, compliance vaults, and dedicated solution architects.
                    </DialogDescription>
                  </div>
                </div>
              </DialogHeader>

              <div className="space-y-3.5 pt-2">
                <div className="space-y-1">
                  <Label className="text-xs font-semibold">Estimated Team Size</Label>
                  <select
                    value={inquiryData.teamSize}
                    onChange={(e) => setInquiryData({ ...inquiryData, teamSize: e.target.value })}
                    className="w-full h-9 rounded-xl border border-input bg-background px-3 py-1 text-xs shadow-xs focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
                  >
                    <option value="25-50">25 - 50 team members</option>
                    <option value="50-150">50 - 150 team members</option>
                    <option value="150-500">150 - 500 team members</option>
                    <option value="500+">500+ team members (Large Enterprise)</option>
                  </select>
                </div>

                <div className="space-y-1">
                  <Label className="text-xs font-semibold">Phone / WhatsApp Number</Label>
                  <Input
                    placeholder="+91 98765 43210"
                    value={inquiryData.phone}
                    onChange={(e) => setInquiryData({ ...inquiryData, phone: e.target.value })}
                    className="text-xs h-9 rounded-xl"
                  />
                </div>

                <div className="space-y-1">
                  <Label className="text-xs font-semibold">Custom Security / Organization Needs</Label>
                  <Textarea
                    placeholder="Tell us about your organization requirements, custom integrations, compliance retention, or setup timeline..."
                    value={inquiryData.message}
                    onChange={(e) => setInquiryData({ ...inquiryData, message: e.target.value })}
                    className="text-xs min-h-[80px] rounded-xl"
                  />
                </div>
              </div>

              <DialogFooter className="pt-2">
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => setEnterpriseModalOpen(false)}
                  className="text-xs rounded-xl"
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  size="sm"
                  disabled={isSubmittingInquiry}
                  className="bg-primary text-primary-foreground text-xs font-bold gap-1.5 rounded-xl cursor-pointer"
                >
                  {isSubmittingInquiry ? "Submitting..." : "Submit Inquiry"}
                </Button>
              </DialogFooter>
            </form>
          </DialogContent>
        </Dialog>
      </div>
    </CRMPageContainer>
  );
}

function renderMatrixCell(val: unknown) {
  if (typeof val === "boolean") {
    return val ? (
      <div className="inline-flex p-1 rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400">
        <Check className="w-3.5 h-3.5 stroke-[2.5]" />
      </div>
    ) : (
      <span className="text-muted-foreground/40 font-bold">—</span>
    );
  }
  if (typeof val === "string") {
    return <span className="font-semibold text-foreground">{val}</span>;
  }
  if (val && typeof val === "object") {
    return <span className="font-semibold text-foreground">{JSON.stringify(val)}</span>;
  }
  return <span className="text-muted-foreground/40 font-bold">—</span>;
}

"use client";

import React, { useEffect, useState, useMemo } from "react";
import {
  Sparkles,
  Bot,
  Layers,
  Edit3,
  Power,
  Check,
  Loader2,
  Cpu,
} from "lucide-react";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { Label } from "@/shared/ui/label";
import { Switch } from "@/shared/ui/switch";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/shared/ui/dialog";
import {
  Table,
  TableHeader,
  TableBody,
  TableRow,
  TableHead,
  TableCell,
} from "@/shared/ui/table";
import { toast } from "sonner";
import {
  fetchPlanAiOverview,
  setPlanDefaultAiModel,
  updatePlanAiConfiguration,
  togglePlatformAiModelAvailability,
  toggleGlobalAiKillswitch,
  PlanAiConfigItem,
  PlatformAiModelItem,
} from "@/shared/lib/api/super-admin.api";
import { CRMPageContainer, CRMPageHeader } from "@/shared/components/crm";

interface ProviderGroup {
  providerKey: string;
  providerName: string;
  models: PlatformAiModelItem[];
  totalCount: number;
  enabledCount: number;
  isEnabled: boolean;
}

export default function SuperAdminAiPage() {
  const [loading, setLoading] = useState(true);
  const [globalAiEnabled, setGlobalAiEnabled] = useState(true);
  const [plans, setPlans] = useState<PlanAiConfigItem[]>([]);
  const [activeChatModels, setActiveChatModels] = useState<PlatformAiModelItem[]>([]);
  const [allModels, setAllModels] = useState<PlatformAiModelItem[]>([]);

  // Modal 1: Edit Plan AI Entitlements
  const [selectedPlanForEdit, setSelectedPlanForEdit] = useState<PlanAiConfigItem | null>(null);
  const [isPlanModalOpen, setIsPlanModalOpen] = useState(false);
  const [planForm, setPlanForm] = useState<{
    aiEnabled: boolean;
    aiLevel: string;
    dailyTokenLimit: number;
    allowedModelIds: string[];
    defaultModelId: string;
  }>({
    aiEnabled: true,
    aiLevel: "Basic AI",
    dailyTokenLimit: 10000,
    allowedModelIds: [],
    defaultModelId: "",
  });
  const [savingPlan, setSavingPlan] = useState(false);

  // Modal 2: Manage Provider Models
  const [selectedProviderKey, setSelectedProviderKey] = useState<string | null>(null);
  const [isProviderModalOpen, setIsProviderModalOpen] = useState(false);
  const [togglingModelId, setTogglingModelId] = useState<string | null>(null);

  const loadData = async () => {
    try {
      setLoading(true);
      const res = await fetchPlanAiOverview();
      setGlobalAiEnabled(res.globalAiEnabled);
      setPlans(res.plans);
      setActiveChatModels(res.activeChatModels);
      setAllModels(res.allModels);
    } catch {
      toast.error("Failed to load AI platform configuration.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    let active = true;
    fetchPlanAiOverview()
      .then((res) => {
        if (!active) return;
        setGlobalAiEnabled(res.globalAiEnabled);
        setPlans(res.plans);
        setActiveChatModels(res.activeChatModels);
        setAllModels(res.allModels);
      })
      .catch(() => {
        if (!active) return;
        toast.error("Failed to load AI platform configuration.");
      })
      .finally(() => {
        if (active) setLoading(false);
      });
    return () => {
      active = false;
    };
  }, []);

  // Filter and order actual CRM subscription plans (Free, Growth, Business)
  const canonicalPlans = useMemo(() => {
    const allowedPlanNames = ["Free", "Growth", "Business"];
    const filtered = plans.filter((p) =>
      allowedPlanNames.some((name) => name.toLowerCase() === p.name.toLowerCase())
    );
    if (filtered.length > 0) {
      return filtered.sort((a, b) => (a.priceNum || 0) - (b.priceNum || 0));
    }
    return plans;
  }, [plans]);

  // Group models by provider dynamically from real data
  const providerGroups: ProviderGroup[] = useMemo(() => {
    const map: Record<string, PlatformAiModelItem[]> = {};
    allModels.forEach((m) => {
      const p = (m.provider || "other").toLowerCase();
      if (!map[p]) map[p] = [];
      map[p].push(m);
    });

    return Object.entries(map).map(([key, models]) => {
      const displayName =
        key === "google"
          ? "Google"
          : key === "openai"
          ? "OpenAI"
          : key === "anthropic"
          ? "Anthropic"
          : key.charAt(0).toUpperCase() + key.slice(1);

      const enabledCount = models.filter(
        (m) => m.isAvailable && m.status === "ENABLED"
      ).length;

      return {
        providerKey: key,
        providerName: displayName,
        models,
        totalCount: models.length,
        enabledCount,
        isEnabled: enabledCount > 0,
      };
    });
  }, [allModels]);

  const totalEnabledModelsCount = useMemo(() => {
    return allModels.filter((m) => m.isAvailable && m.status === "ENABLED").length;
  }, [allModels]);

  // Global Killswitch Toggle
  const handleToggleGlobalKillswitch = async () => {
    const nextState = !globalAiEnabled;
    try {
      const res = await toggleGlobalAiKillswitch(nextState);
      setGlobalAiEnabled(res.globalAiEnabled);
      toast.success(
        nextState
          ? "Platform AI services enabled."
          : "Platform AI services globally disabled."
      );
    } catch {
      toast.error("Failed to toggle global AI state.");
    }
  };

  // Open Edit Plan Modal
  const handleOpenEditPlan = (plan: PlanAiConfigItem) => {
    setSelectedPlanForEdit(plan);
    const allowedIds = plan.allowedModels.map((m) => m.id);
    const defaultId =
      plan.defaultModel?.id ||
      (allowedIds.length > 0 ? allowedIds[0] : activeChatModels[0]?.id || "");

    setPlanForm({
      aiEnabled: plan.aiEnabled,
      aiLevel: plan.aiLevel || "Basic AI",
      dailyTokenLimit: plan.dailyTokenLimit || 10000,
      allowedModelIds: allowedIds,
      defaultModelId: defaultId,
    });
    setIsPlanModalOpen(true);
  };

  // Save Plan Configuration & Default Model
  const handleSavePlan = async () => {
    if (!selectedPlanForEdit) return;

    try {
      setSavingPlan(true);

      // 1. Update Plan configuration (AI enabled, tier level, limits, allowed models)
      const resConfig = await updatePlanAiConfiguration(selectedPlanForEdit.id, {
        aiEnabled: planForm.aiEnabled,
        aiLevel: planForm.aiLevel,
        dailyTokenLimit: Number(planForm.dailyTokenLimit),
        allowedModelIds: planForm.allowedModelIds,
      });

      // 2. If default model changed and is valid, update default model
      if (
        planForm.defaultModelId &&
        planForm.defaultModelId !== selectedPlanForEdit.defaultModel?.id
      ) {
        await setPlanDefaultAiModel(selectedPlanForEdit.id, planForm.defaultModelId);
      }

      if (resConfig.success) {
        toast.success(`Entitlements updated for ${selectedPlanForEdit.name} plan.`);
        setIsPlanModalOpen(false);
        await loadData();
      }
    } catch (err: any) {
      toast.error(
        err.response?.data?.message || err.message || "Failed to update plan configuration."
      );
    } finally {
      setSavingPlan(false);
    }
  };

  // Open Manage Provider Modal
  const handleOpenManageProvider = (providerKey: string) => {
    setSelectedProviderKey(providerKey);
    setIsProviderModalOpen(true);
  };

  const selectedProvider = useMemo(() => {
    if (!selectedProviderKey) return null;
    return providerGroups.find((p) => p.providerKey === selectedProviderKey) || null;
  }, [selectedProviderKey, providerGroups]);

  // Toggle Model Status inside Modal
  const handleToggleModelStatus = async (model: PlatformAiModelItem) => {
    try {
      setTogglingModelId(model.id);
      const nextState = !(model.isAvailable && model.status === "ENABLED");
      const res = await togglePlatformAiModelAvailability(model.id, nextState);
      if (res.success) {
        toast.success(`Model "${model.displayName}" ${nextState ? "enabled" : "disabled"}.`);
        await loadData();
      }
    } catch {
      toast.error("Failed to toggle model availability.");
    } finally {
      setTogglingModelId(null);
    }
  };

  return (
    <CRMPageContainer>
      {/* PAGE HEADER WITH COMPACT AI SERVICES TOGGLE */}
      <CRMPageHeader
        title="AI & Subscription Entitlements"
        subtitle="Manage AI availability, plan entitlements, and available models."
        icon={Sparkles}
      >
        <div className="flex items-center gap-2.5 bg-card border border-border/80 px-3.5 py-1.5 rounded-xl shadow-xs">
          <div
            className={`p-1 rounded-md transition-colors ${
              globalAiEnabled
                ? "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400"
                : "bg-muted text-muted-foreground"
            }`}
          >
            <Power className="w-3.5 h-3.5" />
          </div>
          <div className="flex items-center gap-1.5">
            <span className="text-xs font-bold text-foreground">AI Services</span>
            <span
              className={`text-[10px] font-bold uppercase px-1.5 py-0.5 rounded-md tracking-wide ${
                globalAiEnabled
                  ? "bg-emerald-500/10 text-emerald-700 dark:text-emerald-400 border border-emerald-500/20"
                  : "bg-muted text-muted-foreground border border-border"
              }`}
            >
              {globalAiEnabled ? "Enabled" : "Disabled"}
            </span>
          </div>
          <Switch
            checked={globalAiEnabled}
            onCheckedChange={handleToggleGlobalKillswitch}
            className="data-[state=checked]:bg-emerald-600 ml-1"
          />
        </div>
      </CRMPageHeader>

      {/* SECTION 1 — AI ACCESS BY PLAN */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-sm font-bold text-foreground tracking-tight flex items-center gap-2">
              <Layers className="w-4 h-4 text-emerald-600 dark:text-emerald-400" />
              AI Access by Plan
            </h3>
            <p className="text-xs text-muted-foreground mt-0.5">
              Configure AI availability, model tiers, and token limits per subscription plan.
            </p>
          </div>
        </div>

        {loading ? (
          <div className="p-8 text-center text-xs text-muted-foreground rounded-2xl bg-card border border-border flex items-center justify-center gap-2">
            <Loader2 className="w-4 h-4 animate-spin text-muted-foreground" />
            <span>Loading plan entitlements...</span>
          </div>
        ) : canonicalPlans.length === 0 ? (
          <div className="p-8 text-center text-xs text-muted-foreground rounded-2xl bg-card border border-border">
            No subscription plans found.
          </div>
        ) : (
          <div className="rounded-2xl border border-border/80 bg-card shadow-xs overflow-hidden">
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow className="h-10 hover:bg-transparent">
                    <TableHead className="w-[22%]">Plan</TableHead>
                    <TableHead className="w-[18%]">AI Access</TableHead>
                    <TableHead className="w-[24%]">Default Model</TableHead>
                    <TableHead className="w-[14%]">Models Allowed</TableHead>
                    <TableHead className="w-[14%]">Usage Limit</TableHead>
                    <TableHead className="w-[8%] text-right pr-5">Action</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {canonicalPlans.map((plan) => {
                    const isAiActive = plan.aiEnabled && globalAiEnabled;

                    return (
                      <TableRow key={plan.id} className="h-14 hover:bg-muted/30">
                        {/* Plan Name & Price */}
                        <TableCell className="h-14">
                          <div className="flex items-center gap-2">
                            <span className="font-bold text-foreground text-xs">
                              {plan.name}
                            </span>
                            <span className="text-[11px] font-semibold text-muted-foreground">
                              ({plan.price})
                            </span>
                          </div>
                        </TableCell>

                        {/* AI Access Tier */}
                        <TableCell className="h-14">
                          <span
                            className={`inline-flex items-center text-[11px] font-semibold px-2 py-0.5 rounded-md border ${
                              plan.aiEnabled
                                ? "bg-emerald-500/10 text-emerald-700 dark:text-emerald-400 border-emerald-500/20"
                                : "bg-muted text-muted-foreground border-border"
                            }`}
                          >
                            {plan.aiEnabled ? plan.aiLevel || "Basic AI" : "Disabled"}
                          </span>
                        </TableCell>

                        {/* Default Model */}
                        <TableCell className="h-14">
                          {isAiActive && plan.defaultModel ? (
                            <span className="font-mono text-xs font-semibold text-foreground bg-muted/60 px-2 py-0.5 rounded-md border border-border/60">
                              {plan.defaultModel.displayName}
                            </span>
                          ) : (
                            <span className="text-xs text-muted-foreground italic">
                              {plan.aiEnabled ? "None Selected" : "AI Inactive"}
                            </span>
                          )}
                        </TableCell>

                        {/* Models Allowed */}
                        <TableCell className="h-14">
                          <span className="text-xs font-medium text-foreground">
                            {plan.aiEnabled
                              ? `${plan.allowedModels.length} ${
                                  plan.allowedModels.length === 1 ? "model" : "models"
                                }`
                              : "0 models"}
                          </span>
                        </TableCell>

                        {/* Usage Limit */}
                        <TableCell className="h-14">
                          <span className="text-xs font-medium text-muted-foreground">
                            {plan.dailyTokenLimit
                              ? `${plan.dailyTokenLimit.toLocaleString()} tokens/day`
                              : "Standard"}
                          </span>
                        </TableCell>

                        {/* Action */}
