                      placeholder="15"
                      className="h-8 text-xs font-mono"
                    />
                  </div>
                </div>
              </div>

              {/* Section 4: Bank & Settlement */}
              <div className="bg-muted/15 border border-border/60 rounded-xl p-4.5 space-y-4">
                <h4 className="text-xs font-bold uppercase tracking-wider text-muted-foreground flex items-center gap-1.5 pb-2 border-b border-border/40">
                  <CreditCard className="w-3.5 h-3.5 text-primary" /> Bank & Settlement
                </h4>

                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label className="text-xs font-semibold text-foreground mb-1">Bank Name</Label>
                    <Input
                      value={configForm.bankName || ""}
                      onChange={(e) => setConfigForm({ ...configForm, bankName: e.target.value })}
                      placeholder="HDFC Bank"
                      className="h-8 text-xs"
                    />
                  </div>
                  <div>
                    <div className="flex items-center justify-between mb-1">
                      <Label className="text-xs font-semibold text-foreground">Account Number</Label>
                      <button
                        type="button"
                        onClick={() => setShowAccountNumber(!showAccountNumber)}
                        className="text-[10px] text-muted-foreground hover:text-primary flex items-center gap-1 cursor-pointer transition-colors"
                      >
                        {showAccountNumber ? <EyeOff className="w-3 h-3" /> : <Eye className="w-3 h-3" />}
                        <span>{showAccountNumber ? "Mask" : "Reveal"}</span>
                      </button>
                    </div>
                    <Input
                      type={showAccountNumber ? "text" : "password"}
                      value={configForm.accountNumber || ""}
                      onChange={(e) => setConfigForm({ ...configForm, accountNumber: e.target.value })}
                      placeholder="50200012345678"
                      className="h-8 text-xs font-mono"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label className="text-xs font-semibold text-foreground mb-1">IFSC Code</Label>
                    <Input
                      value={configForm.ifscCode || ""}
                      onChange={(e) => setConfigForm({ ...configForm, ifscCode: e.target.value.toUpperCase() })}
                      placeholder="HDFC0001234"
                      className="h-8 text-xs font-mono"
                    />
                  </div>
                  <div>
                    <Label className="text-xs font-semibold text-foreground mb-1">UPI ID</Label>
                    <Input
                      value={configForm.upiId || ""}
                      onChange={(e) => setConfigForm({ ...configForm, upiId: e.target.value })}
                      placeholder="clixpro@hdfcbank"
                      className="h-8 text-xs"
                    />
                  </div>
                </div>
              </div>
            </div>
          </div>
        </form>
      )}

      {/* CREATE / CONFIGURE SUBSCRIPTION MODAL */}
      {isCreateSubModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-xs">
          <motion.div
            initial={{ opacity: 0, scale: 0.96 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0.96 }}
            className="bg-card border border-border/80 w-full max-w-md rounded-2xl shadow-2xl p-6 space-y-4"
          >
            <div className="flex justify-between items-center">
              <h3 className="text-base font-bold text-foreground flex items-center gap-2">
                <CreditCard className="w-5 h-5 text-primary" /> Configure Subscription
              </h3>
              <button
                onClick={() => setIsCreateSubModalOpen(false)}
                className="text-muted-foreground hover:text-foreground"
              >
                ✕
              </button>
            </div>

            <form onSubmit={handleCreateSubscriptionSubmit} className="space-y-4">
              <div>
                <Label className="text-xs font-semibold text-foreground mb-1">Organization (Workspace) *</Label>
                <select
                  required
                  value={selectedTenantId}
                  onChange={(e) => setSelectedTenantId(e.target.value)}
                  className="w-full h-9 px-3 rounded-xl bg-card border border-border text-xs font-semibold text-foreground shadow-sm focus:outline-none focus:ring-1 focus:ring-primary"
                >
                  <option value="">Select an organization...</option>
                  {organizations.map((org) => (
                    <option key={org.id} value={org.id}>
                      {org.name} ({org.plan?.toUpperCase()} - {org.slug})
                    </option>
                  ))}
                </select>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <Label className="text-xs font-semibold text-foreground mb-1">Plan Tier</Label>
                  <select
                    value={selectedPlanId}
                    onChange={(e) => setSelectedPlanId(e.target.value)}
                    className="w-full h-9 px-3 rounded-xl bg-card border border-border text-xs font-semibold text-foreground shadow-sm focus:outline-none focus:ring-1 focus:ring-primary"
                  >
                    <option value="free">Free Tier</option>
                    <option value="growth">Growth ⭐ (₹499/mo)</option>
                    <option value="business">Business (₹999/mo)</option>
                  </select>
                </div>

                <div>
                  <Label className="text-xs font-semibold text-foreground mb-1">Billing Cycle</Label>
                  <select
                    value={selectedBillingCycle}
                    onChange={(e) => setSelectedBillingCycle(e.target.value as any)}
                    className="w-full h-9 px-3 rounded-xl bg-card border border-border text-xs font-semibold text-foreground shadow-sm focus:outline-none focus:ring-1 focus:ring-primary"
                  >
                    <option value="monthly">Monthly</option>
                    <option value="annual">Annual (Discounted)</option>
                  </select>
                </div>
              </div>

              <div>
                <Label className="text-xs font-semibold text-foreground mb-1">Licensed Seats</Label>
                <Input
                  type="number"
                  min="1"
                  max="1000"
                  required
                  value={selectedSeats}
                  onChange={(e) => setSelectedSeats(Number(e.target.value))}
                  className="h-9 text-xs font-mono font-bold"
                />
              </div>

              <div className="p-3 rounded-xl bg-muted/20 border border-border/60 text-xs text-muted-foreground">
                <p>
                  Setting this will immediately update the organization&apos;s active quota, access tier, and generate a platform invoice.
                </p>
              </div>

              <div className="flex justify-end gap-2 pt-2 border-t border-border/80">
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => setIsCreateSubModalOpen(false)}
                  className="text-xs"
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  size="sm"
                  disabled={isSubmittingSub}
                  className="text-xs font-semibold"
                >
                  {isSubmittingSub ? <Loader2 className="w-3.5 h-3.5 animate-spin mr-1" /> : null}
                  Save Subscription
                </Button>
              </div>
            </form>
          </motion.div>
        </div>
      )}

      {/* PLATFORM REFUND MODAL */}
      {isRefundModalOpen && refundTargetInvoice && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-xs">
          <motion.div
            initial={{ opacity: 0, scale: 0.96 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0.96 }}
            className="bg-card border border-border/80 w-full max-w-md rounded-2xl shadow-2xl p-6 space-y-4"
          >
            <div className="flex justify-between items-center">
              <h3 className="text-base font-bold text-foreground flex items-center gap-2">
                <RotateCcw className="w-5 h-5 text-purple-600" /> Process Platform Refund
              </h3>
              <button
                onClick={() => setIsRefundModalOpen(false)}
                className="text-muted-foreground hover:text-foreground"
              >
                ✕
              </button>
            </div>

            <form onSubmit={handleRefundSubmit} className="space-y-4">
              <div className="p-3 rounded-xl bg-muted/20 border border-border/60 text-xs space-y-1.5">
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Invoice #:</span>
                  <span className="font-mono font-bold text-foreground">{refundTargetInvoice.invoiceNumber}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Organization:</span>
                  <span className="font-semibold text-foreground">{refundTargetInvoice.tenantName}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Paid Amount:</span>
                  <span className="font-mono font-bold text-emerald-600 dark:text-emerald-400">
                    {formatCurrency(refundTargetInvoice.paidAmount, refundTargetInvoice.currency)}
                  </span>
                </div>
              </div>

              <div>
                <Label className="text-xs font-semibold text-foreground mb-1">Refund Amount</Label>
                <Input
                  type="number"
                  step="0.01"
                  min="0.01"
                  max={refundTargetInvoice.paidAmount}
                  required
                  value={refundAmount}
                  onChange={(e) => setRefundAmount(Number(e.target.value))}
                  className="h-9 text-xs font-mono font-bold"
                />
              </div>

              <div>
                <Label className="text-xs font-semibold text-foreground mb-1">Refund Reason *</Label>
                <Textarea
                  rows={2}
                  required
                  placeholder="Enter reason for refund..."
                  value={refundReason}
                  onChange={(e) => setRefundReason(e.target.value)}
                  className="text-xs resize-none"
                />
              </div>

              <div className="flex justify-end gap-2 pt-2 border-t border-border/80">
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => setIsRefundModalOpen(false)}
                  className="text-xs"
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  size="sm"
                  disabled={isProcessingRefund}
                  className="text-xs font-semibold bg-purple-600 hover:bg-purple-700 text-white"
                >
                  {isProcessingRefund ? <Loader2 className="w-3.5 h-3.5 animate-spin mr-1" /> : null}
                  Confirm Refund
                </Button>
              </div>
            </form>
          </motion.div>
        </div>
      )}

      {/* VIEW INVOICE PREVIEW MODAL */}
      {viewInvoiceModalOpen && selectedInvoice && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-xs">
          <motion.div
            initial={{ opacity: 0, scale: 0.96 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0.96 }}
            className="bg-card border border-border/80 w-full max-w-lg rounded-2xl shadow-2xl p-6 space-y-4 max-h-[90vh] overflow-y-auto"
          >
            <div className="flex justify-between items-center border-b border-border/60 pb-3">
              <div className="flex items-center gap-2">
                <FileText className="w-5 h-5 text-primary" />
                <div>
                  <h3 className="text-base font-bold text-foreground font-mono">
                    {selectedInvoice.invoiceNumber}
                  </h3>
                  <p className="text-[11px] text-muted-foreground">Platform SaaS Tax Invoice</p>
                </div>
              </div>
              <button
                onClick={() => setViewInvoiceModalOpen(false)}
                className="text-muted-foreground hover:text-foreground"
              >
                ✕
              </button>
            </div>

            <div className="space-y-4 text-xs">
              <div className="grid grid-cols-2 gap-4 p-4 rounded-xl bg-muted/20 border border-border/60">
                <div>
                  <span className="text-[11px] text-muted-foreground uppercase font-bold block">Billed To</span>
                  <span className="font-bold text-foreground block text-sm mt-0.5">{selectedInvoice.tenantName}</span>
                  <span className="text-muted-foreground block text-[11px]">Tenant ID: {selectedInvoice.tenantId}</span>
                </div>
                <div className="text-right">
                  <span className="text-[11px] text-muted-foreground uppercase font-bold block">Status</span>
                  <div className="mt-1">{getInvStatusBadge(selectedInvoice.status, selectedInvoice.paymentStatus)}</div>
                  <span className="text-[11px] text-muted-foreground block mt-1">
                    Date: {new Date(selectedInvoice.invoiceDate).toLocaleDateString()}
                  </span>
                </div>
              </div>

              <div className="border border-border/60 rounded-xl overflow-hidden">
                <table className="w-full text-xs">
                  <thead className="bg-muted/40 border-b border-border/60 text-muted-foreground font-semibold">
                    <tr>
                      <th className="py-2 px-3 text-left">Description</th>
                      <th className="py-2 px-3 text-center">Seats</th>
                      <th className="py-2 px-3 text-right">Amount</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-border/40">
                    <tr>
                      <td className="py-3 px-3">
                        <span className="font-semibold text-foreground block capitalize">{selectedInvoice.planName} Plan</span>
                        <span className="text-[10px] text-muted-foreground capitalize">{selectedInvoice.billingCycle} billing</span>
                      </td>
                      <td className="py-3 px-3 text-center font-mono">{selectedInvoice.seats}</td>
                      <td className="py-3 px-3 text-right font-mono font-bold text-foreground">
                        {formatCurrency(selectedInvoice.subtotal, selectedInvoice.currency)}
                      </td>
                    </tr>
                  </tbody>
                </table>
              </div>

              <div className="space-y-1.5 pt-2 border-t border-border/60">
                <div className="flex justify-between text-muted-foreground">
                  <span>Subtotal</span>
                  <span className="font-mono">{formatCurrency(selectedInvoice.subtotal, selectedInvoice.currency)}</span>
                </div>
                <div className="flex justify-between text-muted-foreground">
                  <span>GST ({selectedInvoice.taxRate || 18}%)</span>
                  <span className="font-mono">{formatCurrency(selectedInvoice.taxAmount, selectedInvoice.currency)}</span>
                </div>
                <div className="flex justify-between text-sm font-bold text-foreground pt-2 border-t border-border/60">
                  <span>Total Amount</span>
                  <span className="font-mono text-primary">
                    {formatCurrency(selectedInvoice.totalAmount, selectedInvoice.currency)}
                  </span>
                </div>
                <div className="flex justify-between text-xs font-semibold text-emerald-600 dark:text-emerald-400">
                  <span>Amount Paid</span>
                  <span className="font-mono">
                    {formatCurrency(selectedInvoice.paidAmount, selectedInvoice.currency)}
                  </span>
                </div>
              </div>
            </div>

            <div className="flex justify-end pt-3 border-t border-border/60">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setViewInvoiceModalOpen(false)}
                className="text-xs"
              >
                Close
              </Button>
            </div>
          </motion.div>
        </div>
      )}
    </CRMPageContainer>
  );
}

'use client';

import React, { useState, useRef, useEffect } from 'react';
import { useAuth } from '@/features/auth/components/auth-provider';
import { useAIWorkspace, extractMessageText } from '@/features/ai/hooks/use-ai-workspace';
import { AIConversationSidebar } from '@/features/ai/components/AIConversationSidebar';
import { AIChatHeader } from '@/features/ai/components/AIChatHeader';
import { AIEmptyWorkspace } from '@/features/ai/components/AIEmptyWorkspace';
import { AIMessageItem } from '@/features/ai/components/AIMessageItem';
import { AIChatComposer } from '@/features/ai/components/AIChatComposer';
import { SuperAdminTelemetryCard } from '@/features/ai/components/SuperAdminTelemetryCard';
import { CRMPageContainer } from '@/shared/components/crm';
import { toast } from 'sonner';
import { MessageSquare, Activity, X } from 'lucide-react';

export default function SuperAdminAiPage() {
  const { user } = useAuth();
  const [isMobileSidebarOpen, setIsMobileSidebarOpen] = useState(false);
  const [isRightSidebarOpen, setIsRightSidebarOpen] = useState(true);
  const [activeRightTab, setActiveRightTab] = useState<'chats' | 'telemetry'>('chats');

  const {
    messages,
    isLoading,
    error,
    stop,
    clearError,
    setMessages,
    sendMessage,
    confirmAction,

    // Sessions
    currentSessionId,
    groupedSessions,
    historySearchQuery,
    setHistorySearchQuery,
    startNewChat,
    selectSession,
    deleteSession,
    renameSession,
    togglePinSession,
    toggleArchiveSession,
    clearAllHistory,

    // Models & Context
    activeContext,
    clearContext,
    entitledModels,
    selectedModel,
    setSelectedModel,
    aiEnabled,
    globalAiEnabled,
  } = useAIWorkspace();

  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading]);

  const handleCopyTranscript = async () => {
    if (messages.length === 0) {
      toast.info('No messages to copy');
      return;
    }

    try {
      const transcript = messages
        .map((m) => {
          const role = m.role === 'user' ? 'Super Admin' : 'ClixPro AI';
          const content = extractMessageText(m);
          return `### ${role}:\n${content}\n`;
        })
        .join('\n---\n\n');

      await navigator.clipboard.writeText(
        `# ClixProCRM Platform AI Analysis\nDate: ${new Date().toLocaleString()}\n\n${transcript}`
      );
      toast.success('Conversation transcript copied to clipboard');
    } catch {
      toast.error('Failed to copy chat transcript');
    }
  };

  const handleClearMessages = () => {
    if (messages.length === 0) return;
    if (isLoading) stop();
    setMessages([]);
    clearError?.();
    toast.success('Messages cleared');
  };

  const handleSelectPrompt = (prompt: string) => {
    sendMessage(prompt);
    if (isMobileSidebarOpen) setIsMobileSidebarOpen(false);
  };

  const displayMessages = [...messages];
  if (error) {
    let errorMessage = error.message;
    try {
      const parsed = JSON.parse(error.message);
      if (parsed.message) errorMessage = parsed.message;
      if (parsed.error && parsed.error.message) errorMessage = parsed.error.message;
    } catch {}

    displayMessages.push({
      id: 'error-msg',
      role: 'system',
      parts: [
        {
          type: 'text',
          text: `Error: ${
            errorMessage ||
            'An unexpected error occurred while communicating with the ClixPro AI platform.'
          }`,
        },
      ],
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } as any);
  }

  // Right Panel Drawer Content (Chats & Telemetry Tabs)
  const renderRightPanelContent = (isMobile = false) => {
    return (
      <div className="flex-1 flex flex-col h-full overflow-hidden">
        {/* Tab Switcher Header */}
        <div className="p-2.5 sm:p-3 border-b border-border/60 flex items-center justify-between shrink-0 bg-muted/30">
          <div className="flex items-center gap-1 bg-muted/80 p-1 rounded-xl flex-1 mr-2 border border-border/40">
            <button
              onClick={() => setActiveRightTab('chats')}
              className={`flex-1 flex items-center justify-center gap-1.5 py-1.5 px-2.5 rounded-lg text-xs font-semibold transition-all cursor-pointer ${
                activeRightTab === 'chats'
                  ? 'bg-card text-foreground shadow-xs'
                  : 'text-muted-foreground hover:text-foreground'
              }`}
            >
              <MessageSquare className="w-3.5 h-3.5" />
              <span>Chats</span>
              {groupedSessions.totalCount > 0 && (
                <span className="text-[10px] px-1.5 py-0.2 rounded-full bg-primary/10 text-primary font-bold">
                  {groupedSessions.totalCount}
                </span>
              )}
            </button>
            <button
              onClick={() => setActiveRightTab('telemetry')}
              className={`flex-1 flex items-center justify-center gap-1.5 py-1.5 px-2.5 rounded-lg text-xs font-semibold transition-all cursor-pointer ${
                activeRightTab === 'telemetry'
                  ? 'bg-card text-foreground shadow-xs'
                  : 'text-muted-foreground hover:text-foreground'
              }`}
            >
              <Activity className="w-3.5 h-3.5" />
              <span>Telemetry</span>
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
            </button>
          </div>

          <button
            onClick={() => {
              if (isMobile) setIsMobileSidebarOpen(false);
              else setIsRightSidebarOpen(false);
            }}
            className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted/80 transition-colors shrink-0 cursor-pointer"
            title="Close sidebar"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Tab Content */}
        <div className="flex-1 overflow-hidden">
          {activeRightTab === 'chats' ? (
            <div className="h-full animate-in fade-in-50 duration-150">
              <AIConversationSidebar
                groupedSessions={groupedSessions}
                currentSessionId={currentSessionId}
                historySearchQuery={historySearchQuery}
                onSearchChange={setHistorySearchQuery}
                onSelectSession={(s) => {
                  selectSession(s);
                  if (isMobile) setIsMobileSidebarOpen(false);
                }}
                onStartNewChat={() => {
                  startNewChat();
                  if (isMobile) setIsMobileSidebarOpen(false);
                }}
                onDeleteSession={deleteSession}
                onRenameSession={renameSession}
                onTogglePinSession={togglePinSession}
                onToggleArchiveSession={toggleArchiveSession}
                onClearAllHistory={clearAllHistory}
                hideHeader={true}
              />
            </div>
          ) : (
            <div className="h-full overflow-y-auto p-4 animate-in fade-in-50 duration-150 space-y-4 kanban-board-scroll">
              <SuperAdminTelemetryCard onTriggerAnalysis={handleSelectPrompt} />
            </div>
          )}
        </div>
      </div>
    );
  };

  return (
    <CRMPageContainer className="flex-1 h-full min-h-0 gap-0">
      <div className="flex w-full flex-1 h-full min-h-0 overflow-hidden bg-card text-card-foreground border border-sidebar-border/80 dark:border-white/10 shadow-none rounded-2xl">
        {/* 1. Main Chat Workspace (Center) */}
        <main className="flex-1 flex flex-col h-full min-w-0 bg-background/50 relative">
          {/* Header */}
          <AIChatHeader
            onToggleSidebar={() => setIsMobileSidebarOpen(!isMobileSidebarOpen)}
            isSidebarOpen={isMobileSidebarOpen}
            onToggleContextPanel={() => setIsRightSidebarOpen(!isRightSidebarOpen)}
            isContextPanelOpen={isRightSidebarOpen}
            onOpenContextTab={() => {
              setActiveRightTab('telemetry');
              setIsRightSidebarOpen(true);
            }}
            activeContext={activeContext}
            onClearContext={clearContext}
            entitledModels={entitledModels}
            selectedModel={selectedModel}
            onSelectModel={setSelectedModel}
            onCopyTranscript={handleCopyTranscript}
            onClearMessages={handleClearMessages}
            hasMessages={messages.length > 0}
            planName="SUPER_ADMIN"
            isSuperAdmin={true}
          />

          {/* Chat Timeline Area */}
          <div
            className={`flex-1 p-3 sm:p-4 min-h-0 ${
              displayMessages.length === 0
                ? 'flex flex-col items-center justify-center overflow-hidden'
                : 'overflow-y-auto space-y-4'
            }`}
          >
            {displayMessages.length === 0 ? (
              <AIEmptyWorkspace
                onSelectPrompt={handleSelectPrompt}
                userName={user?.name}
                isSuperAdmin={true}
              />
            ) : (
              <div className="max-w-4xl mx-auto w-full">
                {displayMessages.map((msg, idx) => (
                  <AIMessageItem
                    key={msg.id || idx}
                    message={msg as any}
                    onConfirmAction={confirmAction}
                    isLast={idx === displayMessages.length - 1}
                  />
                ))}

                {/* Live Streaming Indicator */}
                {isLoading &&
                  (!displayMessages.length ||
                    displayMessages[displayMessages.length - 1]?.role === 'user') && (
                    <AIMessageItem
                      message={
                        {
                          id: 'streaming-temp',
                          role: 'assistant',
                          parts: [],
                        } as any
                      }
                    />
                  )}
                <div ref={messagesEndRef} />
              </div>
            )}
          </div>

          {/* Input Composer Area (Always Pinned and Visible) */}
          <div className="px-3 py-2 sm:px-5 sm:py-2.5 bg-background/80 backdrop-blur-xs border-t border-border/40 shrink-0">
            <AIChatComposer
              onSendMessage={sendMessage}
              isLoading={isLoading}
              onStop={stop}
              disabled={!globalAiEnabled || !aiEnabled}
              placeholder="Ask ClixPro Platform AI... (Type / for quick commands)"
              isSuperAdmin={true}
              entitledModels={entitledModels}
              selectedModel={selectedModel}
              onSelectModel={setSelectedModel}
              planName="SUPER_ADMIN"
            />
          </div>
        </main>

        {/* 2. Right Expandable Sidebar with Chats (New chat, Search) & Telemetry (Desktop) */}
        <aside
          className={`hidden md:flex shrink-0 h-full flex-col bg-card/60 select-none overflow-hidden transition-all duration-300 ease-[cubic-bezier(0.2,0,0,1)] will-change-[width,opacity] ${
            isRightSidebarOpen
              ? 'w-72 lg:w-80 opacity-100 border-l border-border/60 pointer-events-auto'
              : 'w-0 opacity-0 border-l-0 border-transparent pointer-events-none'
          }`}
          aria-hidden={!isRightSidebarOpen}
        >
          <div className="w-72 lg:w-80 h-full flex flex-col shrink-0">
            {renderRightPanelContent(false)}
          </div>
        </aside>

        {/* 3. Mobile Right Drawer */}
        <div
          className={`fixed inset-0 z-50 md:hidden transition-opacity duration-300 ease-in-out ${
            isMobileSidebarOpen
              ? 'opacity-100 pointer-events-auto'
              : 'opacity-0 pointer-events-none'
          }`}
        >
          <div
            className="absolute inset-0 bg-background/80 backdrop-blur-xs transition-opacity duration-300"
            onClick={() => setIsMobileSidebarOpen(false)}
          />
          <div
            className={`absolute right-0 top-0 bottom-0 w-4/5 max-w-xs h-full bg-card shadow-2xl flex flex-col border-l border-border/60 transition-transform duration-300 ease-[cubic-bezier(0.2,0,0,1)] ${
              isMobileSidebarOpen ? 'translate-x-0' : 'translate-x-full'
            }`}
          >
            {renderRightPanelContent(true)}
          </div>
        </div>
      </div>
    </CRMPageContainer>
  );
}

