            const getTierTheme = () => {
              if (planName.includes("free") || planId.includes("free")) {
                return {
                  icon: Shield,
                  iconBackdrop: "bg-blue-500/20",
                  iconFront: "bg-gradient-to-br from-blue-500 to-indigo-600 shadow-sm shadow-blue-500/25",
