              return {
                icon: Crown,
                iconBackdrop: "bg-amber-500/20",
                iconFront: "bg-gradient-to-br from-amber-500 to-orange-600 shadow-sm shadow-amber-500/25",
                cardBorder: "border-border/80",
                gradientBg: "from-amber-500/[0.03] via-card to-card",
                watermarkIcon: Crown,
