                        variant="outline"
                        onClick={() => {
                          setSubjectDraft(ticket.subject);
                          setIsEditingSubject(false);
                        }}
                        className="h-8 px-2.5 text-xs cursor-pointer shrink-0"
                      >
                        Cancel
