                              return (
                                <div
                                  key={att.id || idx}
                                  onClick={() => {
                                    if (hasUrl) {
                                      if (isImg || isVid) {
                                        setPreviewMedia({
                                          filename: att.fileName,
                                          url: att.fileUrl,
                                          size: att.fileSize,
                                          contentType: att.fileType,
                                          isImage: isImg,
                                          isVideo: isVid,
                                        });
                                      } else {
                                        window.open(att.fileUrl, "_blank", "noopener,noreferrer");
