    const headers = [
      "Ticket #",
      "Subject",
      "Category",
      "Customer Name",
      "Customer Email",
      "Workspace",
      "Priority",
      "Status",
      "Assigned To",
      "Created At",
    ];
    const rows = tickets.map((t) => [
      t.ticketNumber || t.id,
      `"${(t.subject || "").replace(/"/g, '""')}"`,
      `"${(t.category || "").replace(/"/g, '""')}"`,
      `"${(t.createdBy?.name || "").replace(/"/g, '""')}"`,
      `"${(t.createdBy?.email || "").replace(/"/g, '""')}"`,
