            {
              id: 'gpt-4o',
              modelKey: 'gpt-4o',
              displayName: 'GPT-4o (Omni)',
              provider: 'openai',
              description: 'Flagship high-intelligence multimodal model for advanced sales intelligence.',
              contextWindow: 128000,
              capabilities: ['chat', 'summarization', 'lead_scoring', 'function_calling'],
