source:
"use client";

import React, { useState, useEffect, useCallback } from "react";
import {
  ShieldCheck,
  KeyRound,
  AlertCircle,
  ArrowRight,
  Loader2,
  RefreshCw,
  Copy,
  Check,
  Lock,
  Sparkles,
} from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/shared/ui/dialog";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { createClient } from "@/lib/supabase/client";
import { verifyRecoveryCode, recordMfaAuditEvent } from "@/shared/lib/api/mfa.api";
import { useAuth } from "./auth-provider";
import { toast } from "sonner";

interface SuperAdminMfaModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onVerified?: () => void;
  title?: string;
  description?: string;
}

export const SuperAdminMfaModal: React.FC<SuperAdminMfaModalProps> = ({
  open,
  onOpenChange,
  onVerified,
  title = "Super Admin MFA Assurance Required",
  description = "Level 2 Authenticator Assurance (AAL2) is required to access Super Admin platform operations.",
}) => {
  const { refreshUser } = useAuth();
  const [loading, setLoading] = useState(false);
  const [checkingFactors, setCheckingFactors] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [code, setCode] = useState("");
  const [isRecoveryMode, setIsRecoveryMode] = useState(false);
  const [copied, setCopied] = useState(false);

  // Flow mode: "verify" (TOTP exists) or "enroll" (no TOTP yet)
  const [mode, setMode] = useState<"verify" | "enroll">("verify");
  const [targetFactorId, setTargetFactorId] = useState<string | null>(null);
  const [enrollData, setEnrollData] = useState<{
    factorId: string;
    qrCode: string;
    secret: string;
  } | null>(null);

  const initMfaState = useCallback(async () => {
    try {
      setCheckingFactors(true);
      setError(null);
      const supabase = createClient();

      const { data: factorsData, error: factorsErr } =
        await supabase.auth.mfa.listFactors();

      if (factorsErr) {
        throw new Error(factorsErr.message || "Failed to check MFA factors");
      }

      const totpFactors = factorsData?.totp || [];
      const verifiedTotp = totpFactors.find((f: any) => f.status === "verified") || totpFactors[0];

      if (verifiedTotp) {
        setMode("verify");
        setTargetFactorId(verifiedTotp.id);
        setEnrollData(null);
      } else {
        // No TOTP factor exists -> Initialize automatic TOTP enrollment
        setMode("enroll");
        const { data: enrollRes, error: enrollErr } = await supabase.auth.mfa.enroll({
          factorType: "totp",
          friendlyName: "Super Admin Authenticator",
        });

        if (enrollErr || !enrollRes) {
          throw new Error(enrollErr?.message || "Failed to initialize 2FA enrollment");
        }

        setTargetFactorId(enrollRes.id);
        setEnrollData({
          factorId: enrollRes.id,
          qrCode: enrollRes.totp.qr_code,
          secret: enrollRes.totp.secret,
        });
      }
    } catch (err: any) {
      setError(err?.message || "Failed to initialize MFA assurance flow.");
    } finally {
      setCheckingFactors(false);
    }
  }, []);

  const [prevOpen, setPrevOpen] = useState(open);
  if (open !== prevOpen) {
    setPrevOpen(open);
    if (open) {
      setCode("");
      setIsRecoveryMode(false);
    }
  }

  useEffect(() => {
    if (open) {
      initMfaState();
    }
  }, [open, initMfaState]);

  const handleCopySecret = () => {
    if (enrollData?.secret) {
      navigator.clipboard.writeText(enrollData.secret);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
      toast.success("MFA Secret key copied to clipboard");
    }
  };

  const handleVerify = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!code.trim()) return;

    try {
      setLoading(true);
      setError(null);
      const supabase = createClient();

      if (isRecoveryMode) {
        // Verify via backend recovery code
        const res = await verifyRecoveryCode(code.trim());
        if (res.success) {
          await supabase.auth.refreshSession();
          await refreshUser();
          toast.success("MFA Recovery code accepted. AAL2 session activated.");
          setCode("");
          onOpenChange(false);
          onVerified?.();
          return;
        }
      }

      // Normal TOTP Verification or Enrollment Confirmation
      let factorIdToVerify = targetFactorId;
      if (!factorIdToVerify) {
        const { data: fData } = await supabase.auth.mfa.listFactors();
        factorIdToVerify = fData?.totp?.[0]?.id || enrollData?.factorId || "";
      }

      if (!factorIdToVerify) {
        throw new Error("No active MFA factor found to verify.");
      }

      const { data, error: verifyErr } = await supabase.auth.mfa.challengeAndVerify({
        factorId: factorIdToVerify,
        code: code.trim(),
      });

      if (verifyErr || !data) {
        await recordMfaAuditEvent("MFA_CHALLENGE_FAILED", {
          factorId: factorIdToVerify,
          error: verifyErr?.message,
        }).catch(() => {});
        throw new Error(
          verifyErr?.message || "Invalid authentication code. Please check and try again."
        );
      }

      // Record successful verification
      await recordMfaAuditEvent(
        mode === "enroll" ? "MFA_ENROLLED" : "MFA_VERIFIED",
        { factorId: factorIdToVerify }
      ).catch(() => {});

      // Refresh Supabase session to update access token claims to AAL2
      await supabase.auth.refreshSession();
      await refreshUser();

      toast.success("AAL2 Session Assurance Activated. Super Admin Platform unlocked.");
      setCode("");
      onOpenChange(false);
      onVerified?.();
    } catch (err: any) {
      setError(err?.response?.data?.message || err?.message || "Verification failed. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const renderQrCode = (qrCodeStr: string) => {
    if (!qrCodeStr) return null;
    if (
      qrCodeStr.startsWith("data:") ||
      qrCodeStr.startsWith("http://") ||
      qrCodeStr.startsWith("https://") ||
      qrCodeStr.startsWith("blob:")
    ) {
      return (
        <img
          src={qrCodeStr}
          alt="Two-factor authentication QR Code"
          className="w-40 h-40 object-contain rounded-md"
        />
      );
    }
    if (qrCodeStr.trim().startsWith("<svg")) {
      return (
        <div
          className="w-40 h-40 [&>svg]:w-full [&>svg]:h-full"
          dangerouslySetInnerHTML={{ __html: qrCodeStr }}
        />
      );
    }
    return (
      <img
        src={`data:image/svg+xml;utf-8,${encodeURIComponent(qrCodeStr)}`}
        alt="Two-factor authentication QR Code"
        className="w-40 h-40 object-contain rounded-md"
      />
    );
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md border-emerald-500/20 bg-card text-foreground shadow-2xl p-6 overflow-hidden">
        <DialogHeader className="space-y-2 text-left">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20 flex items-center justify-center shadow-sm shrink-0">
              {mode === "enroll" ? (
                <Sparkles className="w-5 h-5" />
              ) : isRecoveryMode ? (
                <KeyRound className="w-5 h-5" />
              ) : (
                <ShieldCheck className="w-5 h-5" />
              )}
            </div>
            <div className="min-w-0 flex-1">
              <div className="flex items-center gap-2 flex-wrap">
                <DialogTitle className="text-base sm:text-lg font-bold tracking-tight text-foreground">
                  {isRecoveryMode ? "Use Backup Recovery Code" : title}
                </DialogTitle>
                <span className="text-[10px] uppercase font-mono font-bold tracking-wider px-2 py-0.5 rounded-full bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20 shrink-0">
                  AAL2 CORE
                </span>
              </div>
              <DialogDescription className="text-xs text-muted-foreground mt-0.5 leading-relaxed">
                {mode === "enroll"
                  ? "Scan the QR code with your authenticator app (Google Authenticator, Authy, 1Password) to link 2FA."
                  : isRecoveryMode
                  ? "Enter one of your 8-character backup recovery codes to verify your session."
                  : description}
              </DialogDescription>
            </div>
          </div>
        </DialogHeader>

        {error && (
          <div className="p-3 bg-destructive/10 border border-destructive/20 rounded-xl flex items-start gap-2.5 text-destructive text-xs font-medium">
            <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
            <span className="leading-relaxed">{error}</span>
          </div>
        )}

        {checkingFactors ? (
          <div className="py-12 flex flex-col items-center justify-center gap-3 text-muted-foreground">
            <Loader2 className="w-7 h-7 animate-spin text-emerald-600" />
            <p className="text-xs font-semibold">Checking Super Admin security assurance level...</p>
          </div>
        ) : (
          <form onSubmit={handleVerify} className="space-y-4 pt-1">
            {/* Enrollment QR & Secret display */}
            {mode === "enroll" && enrollData && !isRecoveryMode && (
              <div className="space-y-3.5 rounded-xl border border-border/80 bg-muted/20 p-4">
                {/* QR Code Container */}
                <div className="flex flex-col items-center justify-center gap-2">
                  <div className="p-3 bg-white rounded-xl shadow-md border border-slate-200 flex items-center justify-center">
                    {enrollData.qrCode ? (
                      renderQrCode(enrollData.qrCode)
                    ) : (
                      <div className="w-40 h-40 flex items-center justify-center text-xs text-muted-foreground">
                        <Loader2 className="w-6 h-6 animate-spin text-emerald-600" />
                      </div>
                    )}
                  </div>
                  <p className="text-[11px] text-muted-foreground font-medium text-center">
                    Point your authenticator camera at the QR code
                  </p>
                </div>

                {/* Secret manual entry */}
                <div className="space-y-1.5 pt-1 border-t border-border/60">
                  <div className="flex items-center justify-between text-xs">
                    <span className="text-[11px] font-semibold text-muted-foreground">
                      Can&apos;t scan QR? Manual Key:
                    </span>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={handleCopySecret}
                      className="h-6 px-2 text-[11px] text-emerald-600 hover:text-emerald-700 hover:bg-emerald-500/10 gap-1"
                    >
                      {copied ? <Check className="w-3 h-3 text-emerald-600" /> : <Copy className="w-3 h-3" />}
                      <span>{copied ? "Copied!" : "Copy Key"}</span>
                    </Button>
                  </div>
                  <div className="flex items-center">
                    <code className="w-full px-3 py-2 rounded-lg bg-background border border-border text-xs font-mono font-bold text-emerald-600 dark:text-emerald-400 select-all tracking-wider text-center break-all shadow-inner">
                      {enrollData.secret}
                    </code>
                  </div>
                </div>
              </div>
            )}

            {/* Code Input */}
            <div className="space-y-1.5">
              <div className="flex items-center justify-between">
                <label className="text-xs font-bold text-foreground">
                  {isRecoveryMode
                    ? "Backup Recovery Code"
                    : mode === "enroll"
                    ? "Enter 6-Digit Code from Authenticator"
                    : "6-Digit Authenticator Security Code"}
                </label>
                <span className="text-[10px] uppercase font-bold text-muted-foreground tracking-wider">
                  {isRecoveryMode ? "Recovery Code" : "TOTP"}
                </span>
              </div>
              <Input
                type="text"
                inputMode={isRecoveryMode ? "text" : "numeric"}
                placeholder={isRecoveryMode ? "ABCD-1234" : "123456"}
                value={code}
                onChange={(e) => setCode(e.target.value)}
                maxLength={isRecoveryMode ? 16 : 6}
                autoFocus
                className="text-center text-xl tracking-[0.35em] font-mono font-extrabold h-12 rounded-xl border-border bg-background focus-visible:ring-2 focus-visible:ring-emerald-500/30 placeholder:tracking-normal placeholder:font-normal placeholder:text-muted-foreground/40 shadow-inner"
                required
              />
            </div>

            <div className="flex flex-col gap-2 pt-2">
              <Button
                type="submit"
                disabled={loading || !code.trim()}
                className="w-full font-bold text-xs gap-2 h-11 rounded-xl bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-500 hover:to-teal-500 text-white shadow-md shadow-emerald-500/20 transition-all"
              >
                {loading ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" />
                    <span>Verifying Session Assurance...</span>
                  </>
                ) : (
                  <>
                    <Lock className="w-4 h-4" />
                    <span>{mode === "enroll" ? "Activate 2FA & Unlock Platform" : "Verify & Unlock Super Admin"}</span>
                    <ArrowRight className="w-4 h-4 ml-auto" />
                  </>
                )}
              </Button>

              {mode === "verify" && (
                <button
                  type="button"
                  onClick={() => {
                    setIsRecoveryMode(!isRecoveryMode);
                    setCode("");
                    setError(null);
                  }}
                  className="text-[11px] text-muted-foreground hover:text-emerald-600 transition-colors font-medium text-center py-1 flex items-center justify-center gap-1.5"
                >
                  <RefreshCw className="w-3 h-3" />
                  <span>
                    {isRecoveryMode
                      ? "Back to Authenticator App Code"
                      : "Lost your authenticator device? Use a backup recovery code"}
                  </span>
                </button>
              )}
            </div>
          </form>
        )}
      </DialogContent>
    </Dialog>
  );
};

"use client";

/**
 * AuthLoadingScreen
 *
 * Polished, minimal, and trustworthy enterprise CRM initialization screen.
 * Designed to feel like Linear, Stripe, Notion, and HubSpot.
 *
 * Features:
 * - Crisp ClixPro brand emblem and logo entrance animation
 * - Clean enterprise typography and visual hierarchy
 * - Dynamic initialization status driven by the actual auth & workspace lifecycle
 * - Ultra-thin, subtle brand accent progress indicator
 * - Timeout & error recovery state ("Something went wrong", "Try again", "Sign out")
 * - Full `prefers-reduced-motion` compliance
 * - Ultra-clean neutral enterprise background with subtle ambient radial illumination
 */

import React, { useEffect, useState, useMemo } from "react";
import { motion, AnimatePresence, useReducedMotion } from "framer-motion";
import { AlertCircle, RotateCcw, LogOut } from "lucide-react";
import { ClixProIcon } from "@/shared/ui/logo";
import { Button } from "@/shared/ui/button";
import { useAuth, type AuthInitStage } from "./auth-provider";

interface AuthLoadingScreenProps {
  heading?: string;
  subheading?: string;
  stage?: AuthInitStage;
  error?: string | null;
  onRetry?: () => void;
  onSignOut?: () => void;
  timeoutMs?: number;
}

const STAGE_CONFIG: Record<
  AuthInitStage,
  { label: string; progress: number }
> = {
  connecting: {
    label: "Connecting securely…",
    progress: 24,
  },
  restoring: {
    label: "Restoring your workspace…",
    progress: 48,
  },
  loading_data: {
    label: "Loading your CRM data…",
    progress: 72,
  },
  preparing: {
    label: "Preparing your dashboard…",
    progress: 92,
  },
  ready: {
    label: "Almost ready…",
    progress: 100,
  },
};

export default function AuthLoadingScreen({
  heading = "Welcome back",
  subheading = "Preparing your workspace…",
  stage: propStage,
  error: propError,
  onRetry,
  onSignOut,
  timeoutMs = 25000,
}: AuthLoadingScreenProps) {
  const prefersReducedMotion = useReducedMotion();

  // Try accessing auth context if available
  let authContext: ReturnType<typeof useAuth> | null = null;
  try {
    // eslint-disable-next-line react-hooks/rules-of-hooks
    authContext = useAuth();
  } catch {
    authContext = null;
  }

  const currentStage: AuthInitStage =
    propStage || authContext?.initStage || "connecting";
  const rawError = propError !== undefined ? propError : authContext?.initError;

  const [hasTimedOut, setHasTimedOut] = useState(false);
  const [isRetrying, setIsRetrying] = useState(false);

  // Setup safety timeout to prevent infinite stuck loading screens
  useEffect(() => {
    if (rawError || currentStage === "ready") return;
    const timer = setTimeout(() => {
      setHasTimedOut(true);
    }, timeoutMs);

    return () => clearTimeout(timer);
  }, [rawError, currentStage, timeoutMs]);

  const handleRetry = async () => {
    setIsRetrying(true);
    setHasTimedOut(false);
    try {
      if (onRetry) {
        await onRetry();
      } else if (authContext?.retryInit) {
        await authContext.retryInit();
      } else if (typeof window !== "undefined") {
        window.location.reload();
      }
    } catch {
      // Handled via context
    } finally {
      setIsRetrying(false);
    }
  };

  const handleSignOut = () => {
    if (onSignOut) {
      onSignOut();
    } else if (authContext?.logout) {
      authContext.logout();
    } else if (typeof window !== "undefined") {
      localStorage.removeItem("has_session");
      window.location.href = "/login";
    }
  };

  const isErrorState = Boolean(rawError || hasTimedOut);
  const currentConfig = STAGE_CONFIG[currentStage] || STAGE_CONFIG.connecting;

  // Animation variants optimized for enterprise calm motion
  const containerVariants: any = useMemo(
    () => ({
      initial: { opacity: 0 },
      animate: {
        opacity: 1,
        transition: {
          duration: prefersReducedMotion ? 0.1 : 0.4,
          ease: "easeOut",
          staggerChildren: prefersReducedMotion ? 0 : 0.08,
        },
      },
      exit: {
        opacity: 0,
        transition: { duration: prefersReducedMotion ? 0.1 : 0.25, ease: "easeOut" },
      },
    }),
    [prefersReducedMotion]
  );

  const itemVariants: any = useMemo(
    () => ({
      initial: prefersReducedMotion ? { opacity: 0 } : { opacity: 0, y: 6 },
      animate: {
        opacity: 1,
        y: 0,
        transition: {
          duration: prefersReducedMotion ? 0.1 : 0.35,
          ease: "easeOut",
        },
      },
    }),
    [prefersReducedMotion]
  );

  return (
    <div
      role="status"
      aria-live="polite"
      aria-label="Workspace initialization"
      className="fixed inset-0 z-50 flex min-h-screen w-full flex-col items-center justify-center overflow-hidden bg-[#fafafa] dark:bg-[#08090a] select-none"
    >
      {/* Subtle enterprise ambient radial illumination */}
      <div
        className="pointer-events-none absolute inset-0 bg-[radial-gradient(ellipse_60%_50%_at_50%_45%,rgba(16,185,129,0.04),transparent_80%)] dark:bg-[radial-gradient(ellipse_60%_50%_at_50%_45%,rgba(16,185,129,0.06),transparent_80%)]"
        aria-hidden="true"
      />

      {/* Main Content Container */}
      <motion.div
        variants={containerVariants}
        initial="initial"
        animate="animate"
        exit="exit"
        className="relative z-10 mx-auto flex w-full max-w-sm flex-col items-center px-6 py-8 text-center"
      >
        <AnimatePresence mode="wait">
          {!isErrorState ? (
            /* Active Initialization State */
            <motion.div
              key="loading-content"
              initial={prefersReducedMotion ? { opacity: 0 } : { opacity: 0, scale: 0.98 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={prefersReducedMotion ? { opacity: 0 } : { opacity: 0, scale: 0.98 }}
              transition={{ duration: 0.25, ease: "easeOut" }}
              className="flex w-full flex-col items-center"
            >
              {/* 1. ClixPro Brand Emblem */}
              <motion.div
                variants={itemVariants}
                className="relative mb-6 flex items-center justify-center"
              >
                <div className="relative flex items-center justify-center p-2 rounded-2xl bg-background/80 dark:bg-card/60 shadow-[0_1px_3px_rgba(0,0,0,0.05),0_10px_20px_-10px_rgba(0,0,0,0.04)] border border-border/60">
                  <ClixProIcon size="lg" pixelSize={38} className="transition-transform" />
                </div>
              </motion.div>

              {/* 2. Welcome Back Heading */}
              <motion.h1
                variants={itemVariants}
                className="text-lg font-semibold tracking-tight text-foreground sm:text-xl"
              >
                {heading}
              </motion.h1>

              {/* 3. Short Supporting Text */}
              <motion.p
                variants={itemVariants}
                className="mt-1 text-sm font-normal text-muted-foreground"
              >
                {subheading}
              </motion.p>

              {/* 4. Minimal Animated Progress Indicator */}
              <motion.div
                variants={itemVariants}
                className="mt-6 w-52 sm:w-56"
              >
                <div className="relative h-[3px] w-full overflow-hidden rounded-full bg-muted/90 dark:bg-muted/50">
                  <motion.div
                    className="h-full rounded-full bg-gradient-to-r from-primary/80 via-primary to-primary/90"
                    initial={{ width: "15%" }}
                    animate={{
                      width: `${currentConfig.progress}%`,
                    }}
                    transition={
                      prefersReducedMotion
                        ? { duration: 0.1 }
                        : {
                            duration: 0.5,
                            ease: "easeInOut",
                          }
                    }
                  />
                </div>
              </motion.div>

              {/* 5. Dynamic Initialization Status */}
              <motion.div
                variants={itemVariants}
                className="mt-3.5 h-5 flex items-center justify-center"
              >
                <AnimatePresence mode="wait">
                  <motion.span
                    key={currentStage}
                    initial={
                      prefersReducedMotion
                        ? { opacity: 0 }
                        : { opacity: 0, y: 3 }
                    }
                    animate={{ opacity: 1, y: 0 }}
                    exit={
                      prefersReducedMotion
                        ? { opacity: 0 }
                        : { opacity: 0, y: -3 }
                    }
                    transition={{ duration: 0.2 }}
                    className="text-xs font-medium text-muted-foreground/80 tracking-normal"
                  >
                    {currentConfig.label}
                  </motion.span>
                </AnimatePresence>
              </motion.div>
            </motion.div>
          ) : (
            /* Error / Timeout Recovery State */
            <motion.div
              key="error-recovery"
              initial={prefersReducedMotion ? { opacity: 0 } : { opacity: 0, scale: 0.98 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={prefersReducedMotion ? { opacity: 0 } : { opacity: 0, scale: 0.98 }}
              transition={{ duration: 0.25, ease: "easeOut" }}
              className="flex w-full flex-col items-center rounded-2xl bg-card/70 dark:bg-card/40 p-6 shadow-sm border border-border/80"
            >
              {/* Error Icon */}
              <div className="mb-4 flex h-10 w-10 items-center justify-center rounded-full bg-destructive/10 text-destructive border border-destructive/20">
                <AlertCircle className="h-5 w-5" />
              </div>

              {/* Error Heading */}
              <h2 className="text-base font-semibold text-foreground">
                Something went wrong
              </h2>

              {/* Error Description */}
              <p className="mt-1.5 text-xs text-muted-foreground max-w-[260px] leading-relaxed">
                We couldn&apos;t prepare your workspace. Please check your connection and try again.
              </p>

              {/* Recovery Actions */}
              <div className="mt-6 flex w-full flex-col gap-2">
                <Button
                  onClick={handleRetry}
                  disabled={isRetrying}
                  size="sm"
                  className="w-full flex items-center justify-center gap-2 h-9 text-xs font-medium"
                >
                  <RotateCcw className={`h-3.5 w-3.5 ${isRetrying ? "animate-spin" : ""}`} />
                  {isRetrying ? "Retrying…" : "Try again"}
                </Button>

                <Button
                  onClick={handleSignOut}
                  variant="ghost"
                  size="sm"
                  className="w-full flex items-center justify-center gap-2 h-8 text-xs text-muted-foreground hover:text-foreground"
                >
                  <LogOut className="h-3.5 w-3.5" />
                  Sign out
                </Button>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>

      {/* Subtle brand attribution at bottom for high-trust enterprise feel */}
      <div className="absolute bottom-6 left-0 right-0 flex items-center justify-center pointer-events-none opacity-40">
        <span className="text-[11px] font-medium tracking-wider uppercase text-muted-foreground">
          ClixPro Enterprise CRM
        </span>
      </div>
    </div>
  );
}

"use client";

import { createContext, useCallback, useContext, useEffect, useMemo, useState, useRef } from "react";
import type React from "react";
import { useQueryClient } from "@tanstack/react-query";
import { fetchCurrentUser, loginUser, logoutUser as clearSessionToken } from "@/shared/lib/api/auth";
import { createClient } from "@/lib/supabase/client";
import { 
  defaultRoleAccess, 
  normalizeRole, 
  type RoleAccess, 
  CRM_ROLES, 
  roleRouteConfig,
  getRolePermissions,
  hasModuleAccess,
  normalizeToModuleTitle,
  navLibrary,
} from "@/shared/lib/auth/rbac";
import { useCRMStore } from "@/shared/store/useCRMStore";

 
const _STORAGE_TOKEN_KEY = "orbit_token";
 
const _STORAGE_USER_KEY = "orbit_user";

type AuthUser = {
  id: string;
  name: string;
  email: string;
  phone?: string;
  role: string;
  roleName?: string;
  displayName?: string;
  avatar?: string | null;
  status?: string;
  tenantId?: string | null;
  companyName?: string;
  companyLogo?: string | null;
  permissions?: string[];
  routes?: string[];
  dashboardWidgets?: string[];
  analyticsVisibility?: RoleAccess["analyticsVisibility"];
  description?: string;
  isSuperAdmin?: boolean;
  isOrgOwner?: boolean;
  isOrgAdmin?: boolean;
};

export type AuthInitStage =
  | "connecting"
  | "restoring"
  | "loading_data"
  | "preparing"
  | "ready";

type AuthStatus = "initializing" | "authenticated" | "unauthenticated";

export type AuthContextState = {
  user: AuthUser | null;
  access: RoleAccess;
  token: string | null;
  loading: boolean;
  isAuthenticated: boolean;
  isInitializing: boolean;
  isHydrated: boolean;
  initStage: AuthInitStage;
  initError: string | null;
  login: (email: string, password: string, staySignedIn?: boolean) => Promise<AuthUser | null | void>;
  logout: () => void;
  refreshUser: () => Promise<void>;
  retryInit: () => Promise<void>;
  hasPermission: (permission: string) => boolean;
};

const AuthContext = createContext<AuthContextState | null>(null);

const WIDGETS_BY_ROLE: Record<string, string[]> = {
  [CRM_ROLES.SUPER_ADMIN]: [
    // Org-wide KPI cards
    "revenue", "newLeads", "activeDeals", "winRate",
    // Widgets
    "salesChart", "upcomingMeetings", "hotLeads", "teamPerformance",
    "leadFunnel", "revenueTracker", "recentActivities", "pendingFollowups",
    "aiInsights", "calendarWidget", "revenueChart", "revenueTarget",
    "recentCustomers",
  ],
  [CRM_ROLES.ADMIN]: [
    // Org-wide KPI cards
    "revenue", "newLeads", "activeDeals", "winRate",
    // Widgets
    "salesChart", "upcomingMeetings", "hotLeads", "teamPerformance",
    "leadFunnel", "revenueTracker", "recentActivities", "pendingFollowups",
    "aiInsights", "calendarWidget", "revenueChart", "revenueTarget",
    "recentCustomers",
  ],
  [CRM_ROLES.MANAGER]: [
    // Team-scoped KPI cards (org-wide metrics visible to managers)
    "revenue", "newLeads", "activeDeals", "winRate",
    // Widgets
    "salesChart", "upcomingMeetings", "hotLeads", "teamPerformance",
    "leadFunnel", "recentActivities", "pendingFollowups", "calendarWidget",
    "revenueChart", "revenueTarget",
  ],
  [CRM_ROLES.SALES]: [
    // Own KPI cards
    "revenue", "activeDeals", "winRate",
    // Widgets
    "salesChart", "upcomingMeetings", "hotLeads", "leadFunnel",
    "recentActivities", "pendingFollowups", "calendarWidget",
  ],
  [CRM_ROLES.SUPPORT]: [
    "upcomingMeetings", "recentActivities", "pendingFollowups", "calendarWidget",
  ],
  // Employee: personal widgets only — no org-wide KPI cards
  [CRM_ROLES.EMPLOYEE]: [
    "myTasks", "myMeetings", "myLeads", "myDeals", "myActivities",
    "upcomingMeetings", "pendingFollowups", "calendarWidget",
  ],
};

function buildAccess(user: AuthUser | null): RoleAccess {
  if (!user) {
    return defaultRoleAccess;
  }

  const roleKey = normalizeRole(user.role);
  const isSuperAdmin = roleKey === CRM_ROLES.SUPER_ADMIN || (user as any).isSuperAdmin === true;

  const allowedRoutes = isSuperAdmin
    ? ["*", ...(roleRouteConfig[CRM_ROLES.SUPER_ADMIN] || [])]
    : roleRouteConfig[roleKey]
    ? [...roleRouteConfig[roleKey]]
    : ["/dashboard"];

  const resolvedPermissions = isSuperAdmin
    ? ["*"]
    : user.permissions && user.permissions.length > 0 
    ? user.permissions 
    : getRolePermissions(roleKey);
    
  if (!allowedRoutes.includes("/ai")) {
    allowedRoutes.push("/ai");
  }

  if (!allowedRoutes.includes("/upgrade")) {
    allowedRoutes.push("/upgrade");
  }

  if (!allowedRoutes.includes("/pricing")) {
    allowedRoutes.push("/pricing");
  }

  if (resolvedPermissions.includes("Help Center") || resolvedPermissions.includes("Support") || roleKey === CRM_ROLES.ADMIN || isSuperAdmin) {
    if (!allowedRoutes.includes("/help")) {
      allowedRoutes.push("/help");
    }
    if (!allowedRoutes.includes("/support")) {
      allowedRoutes.push("/support");
    }
  }

  // Ensure all permitted module routes are dynamically authorized
  for (const perm of resolvedPermissions) {
    const title = normalizeToModuleTitle(perm);
    if (title) {
      const navItem = Object.values(navLibrary).find((n) => n.title === title);
      if (navItem?.href && !allowedRoutes.includes(navItem.href)) {
        allowedRoutes.push(navItem.href);
      }
    }
  }

  return {
    roleName:
      user.roleName ||
      roleKey
        .split("_")
        .map((value) => value.charAt(0).toUpperCase() + value.slice(1))
        .join(" "),
    description: user.description || defaultRoleAccess.description,
    permissions: resolvedPermissions,
    routes: allowedRoutes,
    dashboardWidgets: WIDGETS_BY_ROLE[roleKey] || WIDGETS_BY_ROLE[CRM_ROLES.EMPLOYEE],
    analyticsVisibility: user.analyticsVisibility || "self",
  };
}

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const queryClient = useQueryClient();
  const [status, setStatus] = useState<AuthStatus>("initializing");
  const [user, setUser] = useState<AuthUser | null>(null);
  const [loading, setLoading] = useState(false);
  const [isHydrated, setIsHydrated] = useState(false);
  const [initStage, setInitStage] = useState<AuthInitStage>("connecting");
  const [initError, setInitError] = useState<string | null>(null);
  // Guard: prevents refreshUser() from running during/after an explicit logout.
  // Without this, a stale getSession() result during signOut can restore auth state.
  const isLoggingOut = useRef(false);
  const hasFetched = useRef(false);

  /**
   * cleanupAuthState — clears all React auth state without calling signOut().
   * Used by the SIGNED_OUT event handler to avoid a feedback loop:
   *   logout() → clearSessionToken() → signOut() → SIGNED_OUT → logout() → ...
   */
  const cleanupAuthState = useCallback(() => {
    if (typeof window !== "undefined") {
      localStorage.removeItem("has_session");
      localStorage.removeItem("clixpro_remember_me");
      sessionStorage.removeItem("clixpro_session_active");

      // Defense-in-depth: remove any body-level styles that Radix dialogs may have
      // leaked if they were unmounted during the auth state transition without
      // proper cleanup (e.g., AlertDialog was open when ProtectedRoute unmounted
      // the dashboard tree). These inline styles block interactions on /login.
      document.body.style.removeProperty("pointer-events");
      document.body.style.removeProperty("overflow");
    }
    setUser(null);
    setStatus("unauthenticated");
    setInitStage("connecting");
    setInitError(null);
    setLoading(false);           // Prevent stuck loading state after logout
    setIsHydrated(true);         // Keep hydrated so login page renders immediately (not initializing)
    hasFetched.current = false;  // Allow SIGNED_IN event to re-run refreshUser on next login
    queryClient.clear();
    useCRMStore.getState().reset();
  }, [queryClient]);

  const logout = useCallback(async () => {
    if (isLoggingOut.current) return; // prevent re-entrant calls
    isLoggingOut.current = true;

    // 1. Clean up React state immediately
    cleanupAuthState();

    // 2. Call API to sign out (this fires the SIGNED_OUT event,
    //    which is handled by cleanupAuthState — not logout() — to break the loop)
    try {
      await clearSessionToken(); // hits /api/auth/logout
    } catch (error) {
      console.error("Logout API failed", error);
    } finally {
      isLoggingOut.current = false;
    }
  }, [cleanupAuthState]);

  const refreshUser = useCallback(async () => {
    // Do not run if a logout is in progress.
    // Without this guard, getSession() can return a stale Supabase session
    // (not yet invalidated in client cache) and restore has_session / auth state
    // in the middle of a signOut flow.
    if (isLoggingOut.current) return;

    try {
      setInitError(null);
      setInitStage("connecting");

      let hasSessionLocal = typeof window !== "undefined" ? localStorage.getItem("has_session") : null;
      const isRemembered = typeof window !== "undefined" && localStorage.getItem("clixpro_remember_me") === "1";
      
      // Check if Supabase has a valid session
      const { data: { session } } = await createClient().auth.getSession();
      if (session && !isLoggingOut.current) {
        if (isRemembered && typeof window !== "undefined") {
          localStorage.setItem("has_session", "1");
        }
        hasSessionLocal = "1";
      }

      if (typeof window !== "undefined" && !session && !hasSessionLocal) {
        setStatus("unauthenticated");
        return;
      }

      // Double-check logout guard after the async getSession() call
      if (isLoggingOut.current) return;

      setLoading(true);
      setInitStage("restoring");

      setInitStage("loading_data");
      const currentUser = await fetchCurrentUser();

      // Final guard: if logout happened while fetchCurrentUser was in flight, discard result
      if (isLoggingOut.current) return;

      if (!currentUser) {
        if (typeof window !== "undefined") localStorage.removeItem("has_session");
        setStatus("unauthenticated");
        return;
      }
      setInitStage("preparing");
      setUser(currentUser);
      setStatus("authenticated");
      setInitStage("ready");
     
    } catch (error: any) {
      if (error.message === "NEEDS_ONBOARDING") {
        if (typeof window !== "undefined" && window.location.pathname !== "/onboarding") {
          window.location.href = "/onboarding";
          return;
        }
        setStatus("unauthenticated");
        return;
      }
      console.warn("Auth initialization issue:", error);
      if (typeof window !== "undefined") localStorage.removeItem("has_session");
      setInitError(error?.message || "Failed to restore session");
      setStatus("unauthenticated");
    } finally {
      setLoading(false);
    }
  }, []);

  const retryInit = useCallback(async () => {
    hasFetched.current = false;
    setInitError(null);
    setStatus("initializing");
    setInitStage("connecting");
    await refreshUser().finally(() => setIsHydrated(true));
  }, [refreshUser]);



  useEffect(() => {
    if (hasFetched.current) return;
    hasFetched.current = true;
     
    refreshUser().finally(() => setIsHydrated(true));
  }, [refreshUser]);

  useEffect(() => {
    const {
      data: { subscription },
    } = createClient().auth.onAuthStateChange((event, session) => {
      if (event === 'SIGNED_OUT') {
        // Use cleanupAuthState (not logout) to avoid the feedback loop:
        //   logout() → clearSessionToken() → signOut() → SIGNED_OUT → logout() → ...
        // Supabase has already signed out at this point; we only need to clean React state.
        cleanupAuthState();
      } else if (event === 'SIGNED_IN' || event === 'TOKEN_REFRESHED') {
        // Only run refreshUser if:
        // 1. We haven't fetched yet (e.g. OAuth redirect, page reload with existing session)
        // 2. We're not currently logging out
        // The login() function sets hasFetched.current = true before calling signInWithPassword,
        // so this branch is skipped during the normal email/password login flow — preventing
        // a duplicate fetchCurrentUser race with login()'s own setUser() call.
        if (!hasFetched.current && !isLoggingOut.current && session) {
          hasFetched.current = true;
          refreshUser().finally(() => setIsHydrated(true));
        }
      }
    });

    return () => {
      subscription.unsubscribe();
    };
  }, [cleanupAuthState, refreshUser]);

  const login = useCallback(async (email: string, password: string, rememberMe?: boolean) => {
    try {
      setLoading(true);
      setInitError(null);
      setInitStage("connecting");
      // Mark as fetched BEFORE calling signInWithPassword.
      // This prevents the onAuthStateChange(SIGNED_IN) handler from running a competing
      // refreshUser() at the same time as login()'s own fetchCurrentUser call.
      hasFetched.current = true;
      const response = await loginUser({ email, password, rememberMe });

      setUser(response.data.user);
      setStatus("authenticated");
      setInitStage("ready");
      setInitError(null);
      setIsHydrated(true);
      if (typeof window !== "undefined") {
        localStorage.setItem("has_session", "1");
      }
      
      // Clear cache to ensure fresh data for the new user
      await queryClient.clear();
      return response.data.user;
    } catch (error: any) {
      // If login fails, reset hasFetched so a retry can proceed cleanly
      hasFetched.current = false;
      if (error.message === "NEEDS_ONBOARDING") {
        if (typeof window !== "undefined" && window.location.pathname !== "/onboarding") {
          window.location.href = "/onboarding";
          return;
        }
        setStatus("unauthenticated");
        return;
      }
      throw error;
    } finally {
      setLoading(false);
    }
  }, [queryClient]);

  const value = useMemo<AuthContextState>(() => {
    const access = buildAccess(user);
    return {
      user,
      access,
      token: null, // Token is no longer exposed to frontend
      loading: loading || status === "initializing",
      isAuthenticated: status === "authenticated",
      isInitializing: status === "initializing",
      isHydrated,
      initStage,
      initError,
      login,
      logout,
      refreshUser,
      retryInit,
      hasPermission: (permission: string) => {
        if (!user) return false;
        const roleKey = normalizeRole(user.role);
        if (roleKey === CRM_ROLES.SUPER_ADMIN || roleKey === CRM_ROLES.ADMIN) return true;
        if (access.permissions.includes(permission)) return true;
        return hasModuleAccess(permission, access.permissions, user.role);
      },
    };
  }, [status, user, login, logout, refreshUser, retryInit, loading, isHydrated, initStage, initError]);

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within AuthProvider");
  }
  return context;
}

"use client";

/**
 * PublicRoute
 *
 * Wraps login/register pages. If user is already authenticated,
 * redirect them to /dashboard.
 *
 * During "initializing" phase we show nothing (blank) to avoid
 * flashing the login form to users who are already logged in.
 * The auth loading screen is shown by ProtectedRoute on the dashboard
 * side; public routes just render null during init to stay invisible.
 */

import { useEffect } from "react";
import { useRouter } from "next/navigation";
import { useAuth } from "./auth-provider";
import AuthLoadingScreen from "./auth-loading-screen";

type PublicRouteProps = {
  children: React.ReactNode;
};

export default function PublicRoute({ children }: PublicRouteProps) {
  const router = useRouter();
  const { isAuthenticated, isInitializing, user } = useAuth();

  useEffect(() => {
    if (!isInitializing && isAuthenticated && user) {
      const isSuperAdmin =
        user.role?.toUpperCase() === "SUPER_ADMIN" ||
        user.role?.toUpperCase() === "SUPER ADMIN" ||
        (user as any)?.isSuperAdmin === true;

      if (isSuperAdmin) {
        router.replace("/super-admin");
      } else {
        router.replace("/dashboard");
      }
    }
  }, [isAuthenticated, isInitializing, router, user]);

  // During init or when redirecting authenticated user, show loading screen instead of blank null
  if (isInitializing || isAuthenticated) {
    return <AuthLoadingScreen error={null} stage={isAuthenticated ? "ready" : undefined} />;
  }

  return <>{children}</>;
}

"use client";

import { useEffect } from "react";
import { useRouter } from "next/navigation";
import { useAuth } from "./auth-provider";
import AuthLoadingScreen from "./auth-loading-screen";

type SuperAdminRouteProps = {
  children: React.ReactNode;
};

export default function SuperAdminRoute({ children }: SuperAdminRouteProps) {
  const router = useRouter();
  const { isAuthenticated, isInitializing, user } = useAuth();

  useEffect(() => {
    if (isInitializing) return;

    if (!isAuthenticated) {
      router.replace("/login");
      return;
    }

    const isSuperAdmin =
      user?.role?.toUpperCase() === "SUPER_ADMIN" ||
      user?.role?.toUpperCase() === "SUPER ADMIN" ||
      (user as any)?.isSuperAdmin === true;

    if (!isSuperAdmin) {
      // Non-super-admin user attempting to access /super-admin
      router.replace("/dashboard");
    }
  }, [isAuthenticated, isInitializing, router, user]);

  if (isInitializing || (isAuthenticated && !user) || !isAuthenticated) {
    return <AuthLoadingScreen />;
  }

  const isSuperAdmin =
    user?.role?.toUpperCase() === "SUPER_ADMIN" ||
    user?.role?.toUpperCase() === "SUPER ADMIN" ||
    (user as any)?.isSuperAdmin === true;

  if (!isSuperAdmin) {
    return <AuthLoadingScreen />;
  }

  return <>{children}</>;
}

