                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setShowDisableModal(true)}
                  className="font-bold text-xs gap-1.5 h-8.5 text-destructive hover:text-destructive hover:bg-destructive/10"
