              className="font-bold text-xs gap-1.5 h-8.5 shrink-0"
            >
              {isExporting ? (
                <Loader2 className="w-3.5 h-3.5 animate-spin" />
              ) : (
                <Download className="w-3.5 h-3.5" />
              )}
              {isExporting ? "Exporting..." : "Export My Data"}
            </Button>
          </div>
        </CRMCard>
      </div>

