              </Button>
            </div>
            <Button size="sm" onClick={() => setShowRecoveryModal(false)} className="font-bold text-xs h-8">
              Done
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import {
  Laptop,
  Smartphone,
  Tablet,
  Globe,
  LogOut,
  Loader2,
} from "lucide-react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { CRMCard } from "@/shared/components/crm";
import { Button } from "@/shared/ui/button";
import { Badge } from "@/shared/ui/badge";
import { Skeleton } from "@/shared/ui/skeleton";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/shared/ui/dialog";
import {
  fetchUserSessions,
  revokeUserSession,
  revokeAllOtherSessions,
} from "@/shared/lib/api/sessions.api";
import { toast } from "sonner";

export default function SessionsSettings() {
  const queryClient = useQueryClient();
  const [showRevokeAllModal, setShowRevokeAllModal] = useState(false);
  const [revokingSessionId, setRevokingSessionId] = useState<string | null>(null);

  const {
    data: sessionsData,
    isLoading: sessionsLoading,
    isError: sessionsError,
  } = useQuery({
    queryKey: ["user-sessions"],
    queryFn: fetchUserSessions,
    staleTime: 30_000,
  });

  const revokeMutation = useMutation({
    mutationFn: (sessionId: string) => revokeUserSession(sessionId),
    onMutate: (id) => setRevokingSessionId(id),
    onSuccess: () => {
      toast.success("Session revoked successfully");
      void queryClient.invalidateQueries({ queryKey: ["user-sessions"] });
      void queryClient.invalidateQueries({ queryKey: ["security-activity"] });
    },
    onError: (err: any) => {
      toast.error(err?.response?.data?.message || err?.message || "Failed to revoke session");
    },
    onSettled: () => setRevokingSessionId(null),
  });

  const revokeAllMutation = useMutation({
    mutationFn: revokeAllOtherSessions,
    onSuccess: () => {
      toast.success("All other sessions signed out");
      setShowRevokeAllModal(false);
      void queryClient.invalidateQueries({ queryKey: ["user-sessions"] });
      void queryClient.invalidateQueries({ queryKey: ["security-activity"] });
    },
    onError: (err: any) => {
      toast.error(err?.response?.data?.message || err?.message || "Failed to sign out sessions");
    },
  });

  const getDeviceIcon = (deviceType?: string) => {
    switch (deviceType?.toLowerCase()) {
      case "desktop":
        return <Laptop className="w-4 h-4" />;
      case "mobile":
        return <Smartphone className="w-4 h-4" />;
      case "tablet":
        return <Tablet className="w-4 h-4" />;
      default:
        return <Globe className="w-4 h-4" />;
    }
  };

  const formatSessionTime = (isoString?: string) => {
    if (!isoString) return "Recently";
    try {
      const d = new Date(isoString);
      return d.toLocaleString(undefined, {
        month: "short",
        day: "numeric",
        hour: "2-digit",
        minute: "2-digit",
      });
    } catch {
      return "Recently";
    }
  };

  return (
    <div className="min-h-full flex-1 flex flex-col">
      <CRMCard className="min-h-full flex-1 flex flex-col">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-5 border-b border-border/50">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center text-primary">
              <Laptop className="w-4 h-4" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="text-base font-bold text-foreground">Active Login Sessions</h3>
                {sessionsData?.activeCount !== undefined && (
                  <Badge variant="outline" className="text-[10px] font-bold text-primary bg-primary/10 border-primary/20">
                    {sessionsData.activeCount} Active
                  </Badge>
                )}
              </div>
              <p className="text-xs text-muted-foreground font-medium mt-0.5">
                Manage all devices and browser sessions currently logged into your account.
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            {sessionsData?.sessions && sessionsData.sessions.filter((s) => !s.isCurrent && !s.isRevoked).length > 0 && (
              <Button
                variant="outline"
                size="sm"
                onClick={() => setShowRevokeAllModal(true)}
                className="text-xs font-semibold gap-1.5 h-9 text-destructive hover:text-destructive hover:bg-destructive/10"
              >
                <LogOut className="w-3.5 h-3.5" />
                Sign Out Others
              </Button>
            )}
          </div>
        </div>

        {sessionsLoading ? (
          <div className="mt-4 space-y-3">
            {Array.from({ length: 4 }).map((_, i) => (
              <div
                key={i}
                className="p-4 rounded-xl border border-border/60 bg-muted/20 flex flex-col sm:flex-row sm:items-center justify-between gap-3"
              >
                <div className="flex items-start gap-3 flex-1">
                  <Skeleton className="w-9 h-9 rounded-lg shrink-0 mt-0.5" />
                  <div className="space-y-1.5 flex-1">
                    <div className="flex items-center gap-2">
                      <Skeleton className="h-4 w-44" />
                      {i === 0 && <Skeleton className="h-4.5 w-20 rounded-full" />}
                    </div>
                    <div className="flex items-center gap-3">
                      <Skeleton className="h-3 w-20" />
                      <Skeleton className="h-3 w-28" />
                      <Skeleton className="h-3 w-24" />
                    </div>
                  </div>
                </div>
                <div className="flex justify-end shrink-0">
                  <Skeleton className="h-7 w-20 rounded-lg" />
                </div>
              </div>
            ))}
          </div>
        ) : sessionsError ? (
          <div className="p-4 mt-4 bg-destructive/10 border border-destructive/20 rounded-lg text-destructive text-xs font-medium">
            Failed to load active sessions. Please refresh the page.
          </div>
        ) : (
          <div className="mt-4 space-y-3">
            {sessionsData?.sessions && sessionsData.sessions.length > 0 ? (
              sessionsData.sessions.map((session) => (
                <div
                  key={session.id}
                  className={`p-4 rounded-xl border transition-all flex flex-col sm:flex-row sm:items-center justify-between gap-3 text-xs ${
                    session.isCurrent
                      ? "border-primary/40 bg-primary/[0.03]"
                      : session.isRevoked
                      ? "border-border/30 bg-muted/20 opacity-60"
                      : "border-border/60 bg-muted/20 hover:border-border"
                  }`}
                >
                  <div className="flex items-start gap-3">
                    <div
                      className={`w-9 h-9 rounded-lg flex items-center justify-center shrink-0 mt-0.5 ${
                        session.isCurrent
                          ? "bg-primary/10 text-primary"
                          : session.isRevoked
                          ? "bg-muted text-muted-foreground"
                          : "bg-background border border-border/60 text-foreground"
                      }`}
                    >
                      {getDeviceIcon(session.deviceType)}
                    </div>
                    <div className="space-y-0.5">
                      <div className="flex items-center gap-2">
                        <span className="font-bold text-foreground">
                          {session.browser || "Web Browser"} on {session.operatingSystem || "Device"}
                        </span>
                        {session.isCurrent && (
                          <Badge variant="success" className="text-[9px] font-bold uppercase tracking-wider px-1.5 py-0.2">
                            This Device
                          </Badge>
                        )}
                        {session.isRevoked && (
                          <Badge variant="neutral" className="text-[9px] font-bold uppercase tracking-wider px-1.5 py-0.2">
                            Revoked
                          </Badge>
                        )}
                      </div>
                      <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-[11px] text-muted-foreground font-medium">
                        {session.ipAddress && <span>IP: {session.ipAddress}</span>}
                        <span>•</span>
                        <span>{session.isCurrent ? "Active now" : `Last active: ${formatSessionTime(session.lastActiveAt)}`}</span>
                        <span>•</span>
                        <span>Signed in: {new Date(session.createdAt).toLocaleDateString()}</span>
                      </div>
                    </div>
                  </div>

                  {!session.isCurrent && !session.isRevoked && (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => revokeMutation.mutate(session.id)}
                      disabled={revokingSessionId === session.id}
                      className="text-xs font-bold text-destructive hover:bg-destructive/10 hover:text-destructive h-8 px-3 shrink-0"
                    >
                      {revokingSessionId === session.id ? (
                        <Loader2 className="w-3.5 h-3.5 animate-spin mr-1" />
                      ) : (
                        <LogOut className="w-3.5 h-3.5 mr-1" />
                      )}
                      Revoke
                    </Button>
                  )}
                </div>
              ))
            ) : (
              <div className="p-8 text-center text-xs text-muted-foreground font-medium border border-dashed rounded-xl">
                No active session records found.
              </div>
            )}
          </div>
        )}
      </CRMCard>

      {/* Revoke All Other Sessions Confirmation Dialog */}
      <Dialog open={showRevokeAllModal} onOpenChange={setShowRevokeAllModal}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="text-base font-bold flex items-center gap-2 text-destructive">
              <LogOut className="w-4 h-4" />
              Sign Out All Other Sessions
            </DialogTitle>
            <DialogDescription className="text-xs text-muted-foreground">
              This action will revoke all active sessions on other browsers and mobile devices. You will remain signed in on this current browser.
            </DialogDescription>
          </DialogHeader>

          <DialogFooter className="pt-3">
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={() => setShowRevokeAllModal(false)}
              disabled={revokeAllMutation.isPending}
              className="text-xs"
            >
              Cancel
            </Button>
            <Button
              type="button"
              variant="destructive"
              size="sm"
              onClick={() => revokeAllMutation.mutate()}
              disabled={revokeAllMutation.isPending}
              className="text-xs font-semibold gap-1.5"
            >
              {revokeAllMutation.isPending ? (
                <Loader2 className="w-3.5 h-3.5 animate-spin" />
              ) : (
                <LogOut className="w-3.5 h-3.5" />
              )}
              Sign Out Other Devices
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import React, { useState, useEffect, useRef } from "react";
import {
  Building2,
  Hash,
  Globe,
  MapPin,
  Save as SaveIcon,
  Loader2,
  Upload,
  Trash2 as Trash2Icon,
  Pencil,
  X,
  Palette,
  Check as CheckIcon,
  ShieldCheck as ShieldCheckIcon,
} from "lucide-react";
import { Input } from "@/shared/ui/input";
import { Label } from "@/shared/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/ui/select";
import { Button } from "@/shared/ui/button";
import { Badge } from "@/shared/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogTitle,
} from "@/shared/ui/dialog";
import { CRMCard } from "@/shared/components/crm";
import { ImageCropperModal } from "@/shared/components/ImageCropperModal";
import { AppIcon } from "@/shared/components/icons/icon-registry";
import {
  useWorkspace,
  useUpdateWorkspace,
  useUploadWorkspaceLogo,
} from "@/shared/hooks/use-settings";
import { PageErrorState } from "@/shared/components/crm/PageFeedbackStates";
import { WorkspaceSettingsSkeleton } from "./SettingsSkeletons";
import { useCurrency } from "@/shared/hooks/use-currency";
import { useCRMStore } from "@/shared/store/useCRMStore";
import { useAuth } from "@/features/auth/components/auth-provider";
import { useQueryClient } from "@tanstack/react-query";
import {
  toValidHex7,
  isValidHexColor,
  extractLogoPalette,
} from "@/shared/lib/utils/color-utils";
import { toast } from "sonner";

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB

const PRESET_BRAND_SWATCHES = [
  { name: "Emerald", hex: "#10b981" },
  { name: "Blue", hex: "#3b82f6" },
  { name: "Indigo", hex: "#6366f1" },
  { name: "Violet", hex: "#8b5cf6" },
  { name: "Rose", hex: "#f43f5e" },
  { name: "Amber", hex: "#f59e0b" },
];

function getInitials(name?: string) {
  if (!name) return "WS";
  return name
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part.charAt(0).toUpperCase())
    .join("");
}

const normalizeCurrency = (curr?: string | null) => {
  if (!curr) return "INR";
  return curr.toUpperCase() === "INR" ? "INR" : "INR";
};

const normalizeTimezone = (tz?: string | null) => {
  if (!tz) return "ist";
  return tz.toLowerCase() === "ist" || tz === "Asia/Kolkata" ? "ist" : "ist";
};

const WorkspaceSettings = () => {
  const { data: workspace, isLoading: loading, error, refetch } = useWorkspace();
  const mutation = useUpdateWorkspace();
  const uploadLogoMutation = useUploadWorkspaceLogo();
  const { CurrencyIcon } = useCurrency();
  const setStoreCurrency = useCRMStore((state) => state.setCurrency);
  const setAccentColor = useCRMStore((state) => state.setAccentColor);
  const { refreshUser } = useAuth();
  const queryClient = useQueryClient();

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [uploadingLogo, setUploadingLogo] = useState(false);
  const [cropModalOpen, setCropModalOpen] = useState(false);
  const [selectedRawFile, setSelectedRawFile] = useState<File | null>(null);
  const [editModalOpen, setEditModalOpen] = useState(false);
  const [logoColors, setLogoColors] = useState<string[]>([]);

  const [formData, setFormData] = useState({
    name: "",
    taxId: "",
    currency: "INR",
    timezone: "ist",
    address: "",
    logo: null as string | null,
    brandPrimaryColor: "#10b981",
  });

  const [prevLogo, setPrevLogo] = useState(workspace?.logo);
  if (workspace?.logo !== prevLogo) {
    setPrevLogo(workspace?.logo);
    if (!workspace?.logo) {
      setLogoColors([]);
    }
  }

  useEffect(() => {
    if (!workspace?.logo) return;
    let active = true;
    void extractLogoPalette(workspace.logo, 6).then((colors) => {
      if (!active) return;
      if (colors && colors.length > 0) {
        setLogoColors(colors);
      } else {
        setLogoColors([]);
      }
    });
    return () => {
      active = false;
    };
  }, [workspace?.logo]);

  // Sync form data when workspace data loads or updates
  const [prevWorkspace, setPrevWorkspace] = useState(workspace);
  if (workspace && workspace !== prevWorkspace) {
    setPrevWorkspace(workspace);
    const activeColor = workspace.brandPrimaryColor || "#10b981";
    setFormData({
      name: workspace.name || "",
      taxId: workspace.taxId || "",
      currency: normalizeCurrency(workspace.currency),
      timezone: normalizeTimezone(workspace.timezone),
      address: workspace.address || "",
      logo: workspace.logo || null,
      brandPrimaryColor: activeColor,
    });
  }

  useEffect(() => {
    if (workspace?.currency) {
      setStoreCurrency(workspace.currency);
    }
    if (workspace?.brandPrimaryColor) {
      setAccentColor(workspace.brandPrimaryColor);
    }
  }, [workspace?.currency, workspace?.brandPrimaryColor, setStoreCurrency, setAccentColor]);

  const handleSelectRawFile = (file: File) => {
    if (!file.type.startsWith("image/")) {
      toast.error("Please upload a valid image file (PNG, JPG, or WebP)");
      return;
    }

    if (file.size > MAX_FILE_SIZE) {
      toast.error("Image file size must be less than 5MB");
      return;
    }

    setSelectedRawFile(file);
    setCropModalOpen(true);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      handleSelectRawFile(file);
    }
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files?.[0];
    if (file) {
      handleSelectRawFile(file);
    }
  };

  const handleCropComplete = async (croppedFile: File) => {
    setUploadingLogo(true);
    try {
      const result = await uploadLogoMutation.mutateAsync(croppedFile);
      if (result?.logo) {
        setFormData((prev) => ({
          ...prev,
          logo: result.logo,
          brandPrimaryColor: result.brandPrimaryColor || prev.brandPrimaryColor,
        }));
        if (result.brandPrimaryColor) {
          setAccentColor(result.brandPrimaryColor);
        }
        queryClient.invalidateQueries({ queryKey: ["workspace"] });
        void refreshUser();
        toast.success("Workspace logo updated successfully!");
      }
    } catch (err: any) {
      toast.error(
        err?.response?.data?.message || err?.message || "Failed to upload workspace logo"
      );
    } finally {
      setUploadingLogo(false);
    }
  };

  const handleRemoveLogo = () => {
    mutation.mutate(
      { ...formData, logo: null, brandPrimaryColor: "#10b981" },
      {
        onSuccess: () => {
          setFormData((prev) => ({ ...prev, logo: null, brandPrimaryColor: "#10b981" }));
          setLogoColors([]);
          setAccentColor("#10b981");
          queryClient.invalidateQueries({ queryKey: ["workspace"] });
          void refreshUser();
          toast.success("Logo removed successfully");
        },
        onError: (err: any) => {
          toast.error(err?.response?.data?.message || err?.message || "Failed to remove logo");
        },
      }
    );
  };

  const handleOpenEditModal = () => {
    if (workspace) {
      setFormData({
        name: workspace.name || "",
        taxId: workspace.taxId || "",
        currency: normalizeCurrency(workspace.currency),
        timezone: normalizeTimezone(workspace.timezone),
        address: workspace.address || "",
        logo: workspace.logo || null,
        brandPrimaryColor: workspace.brandPrimaryColor || "#10b981",
      });
    }
    setEditModalOpen(true);
  };

  const handleSaveModal = (e: React.FormEvent) => {
    e.preventDefault();
    mutation.mutate(formData, {
      onSuccess: () => {
        if (formData.currency) {
          setStoreCurrency(formData.currency);
        }
        if (formData.brandPrimaryColor) {
          setAccentColor(formData.brandPrimaryColor);
        }
        queryClient.invalidateQueries({ queryKey: ["workspace"] });
        void refreshUser();
        setEditModalOpen(false);
        toast.success("Workspace details updated successfully!");
      },
      onError: (err: any) => {
        toast.error(
          err?.response?.data?.message ||
            err?.message ||
            "Failed to update workspace details"
        );
      },
    });
  };

  const handleColorChange = (hex: string) => {
    setFormData((prev) => ({ ...prev, brandPrimaryColor: hex }));
    if (isValidHexColor(hex)) {
      setAccentColor(hex);
    }
  };

  if (loading) {
    return <WorkspaceSettingsSkeleton />;
  }

  if (error) {
    return (
      <PageErrorState
        title="Workspace settings unavailable"
        message={(error as Error).message}
        onRetry={() => {
          void refetch();
        }}
      />
    );
  }

  const initials = getInitials(workspace?.name || undefined);
  const displaySwatches =
    formData.logo && logoColors.length > 0
      ? logoColors.map((hex) => ({ name: hex, hex }))
      : PRESET_BRAND_SWATCHES;

  return (
    <div className="space-y-3.5 min-h-full flex flex-col">
      {/* Hidden File Input */}
      <input
        ref={fileInputRef}
        type="file"
        accept="image/png,image/jpeg,image/jpg,image/webp"
        className="hidden"
        onChange={handleFileChange}
      />

      {/* Image Cropper Modal */}
      <ImageCropperModal
        open={cropModalOpen}
        onOpenChange={setCropModalOpen}
        imageFile={selectedRawFile}
        onCropComplete={(croppedFile) => {
          void handleCropComplete(croppedFile);
        }}
        title="Crop Workspace Logo"
        description="Position and crop your company logo for crisp display across CRM, invoices, and quotations."
      />

      {/* Workspace Identity Card */}
      <CRMCard className="p-3.5 sm:p-4.5">
        <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
          {/* Left section: Logo + Name & Subtitle */}
          <div className="flex items-center gap-3.5 min-w-0 w-full sm:w-auto">
            {/* Logo Box */}
            <div
              onDragOver={handleDragOver}
              onDragLeave={handleDragLeave}
              onDrop={handleDrop}
              onClick={() => !uploadingLogo && fileInputRef.current?.click()}
              className={`relative group cursor-pointer w-13 h-13 sm:w-14 sm:h-14 rounded-xl border transition-all flex items-center justify-center overflow-hidden bg-muted/40 backdrop-blur-sm shadow-xs shrink-0 ${
                isDragging
                  ? "border-primary bg-primary/10 ring-2 ring-primary/20 scale-[1.02]"
                  : "border-border/70 hover:border-primary/60 hover:bg-muted/60"
              }`}
            >
              {uploadingLogo ? (
                <div className="flex flex-col items-center justify-center p-1 text-center gap-0.5">
                  <Loader2 className="w-4 h-4 animate-spin text-primary" />
                  <span className="text-[8px] font-semibold text-muted-foreground">Uploading</span>
                </div>
              ) : workspace?.logo ? (
                <div className="relative w-full h-full p-2 flex items-center justify-center">
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <img
                    src={workspace.logo}
                    alt={workspace.name || "Company Logo"}
                    className="w-full h-full object-contain transition-transform group-hover:scale-105"
                  />
                  <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center text-white rounded-xl gap-0.5">
                    <AppIcon name="upload" icon={Upload} size={13} className="text-white" />
                    <span className="text-[8.5px] font-semibold">Change</span>
                  </div>
                </div>
              ) : (
                <div className="relative w-full h-full flex items-center justify-center">
                  <div className="bg-gradient-to-br from-primary to-primary/70 text-primary-foreground text-base sm:text-lg font-bold w-full h-full rounded-xl flex items-center justify-center select-none shadow-xs">
                    {initials}
                  </div>
                  <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center text-white rounded-xl gap-0.5">
                    <AppIcon name="upload" icon={Upload} size={13} className="text-white" />
                    <span className="text-[8.5px] font-semibold">Upload</span>
                  </div>
                </div>
              )}
            </div>

            {/* Name and Tagline */}
            <div className="min-w-0 flex-1">
              <div className="flex items-center gap-1.5">
                <h2 className="text-base sm:text-lg font-bold tracking-tight text-foreground truncate">
                  {workspace?.name || "My Workspace"}
                </h2>
                <Badge variant="success" className="px-1.5 py-0.2 text-[8.5px] font-bold uppercase tracking-widest">
                  Verified
                </Badge>
              </div>
              <p className="text-xs text-muted-foreground font-medium truncate">
                {workspace?.taxId ? `GSTIN: ${workspace.taxId}` : "Business Workspace"}
              </p>
            </div>
          </div>

          {/* Right section: Badge + Action Buttons + Specs */}
          <div className="flex flex-col items-start sm:items-end gap-1 shrink-0 w-full sm:w-auto">
            <div className="flex flex-wrap items-center gap-2">
