"use client";

import React, { useState, useMemo, useEffect, useCallback } from "react";
import { useForm, useFieldArray } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import {
  Dialog,
  DialogContent,
  DialogTitle,
  DialogDescription,
} from "@/shared/ui/dialog";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormMessage,
} from "@/shared/ui/form";
import { Input } from "@/shared/ui/input";
import { Textarea } from "@/shared/ui/textarea";
import { Button } from "@/shared/ui/button";
import { Label } from "@/shared/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/ui/select";
import { FormSubmitButton } from "@/shared/components/form-submit-button";
import { AppIcon } from "@/shared/components/icons/icon-registry";
import { UnsavedWarning } from "@/shared/components/unsaved-warning";
import { useDirtyForm } from "@/shared/hooks/use-dirty-form";
import { useCreateTask, useUpdateTask, useEmployees } from "@/shared/hooks/use-crm";
import { useAuth } from "@/features/auth/components/auth-provider";
import { TaskType, TaskAttachment } from "@/shared/types/task";
import { AlertCircle } from "lucide-react";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/shared/ui/tabs";
import { TaskRelatedRecordPicker, RelatedRecord } from "./TaskRelatedRecordPicker";
import { TaskChecklistTab } from "./TaskChecklistTab";

// ─── Schema (essential fields only) ───

export const taskFormSchema = z.object({
  title: z.string().min(2, "Title must be at least 2 characters"),
  description: z.string(),
  assignedToId: z.string().min(1, "Please assign this task"),
  priority: z.enum(["URGENT", "HIGH", "MEDIUM", "LOW"]),
  dueDate: z.string().min(1, "Due date is required"),
  checklist: z.array(
    z.object({
      id: z.string(),
      title: z.string().min(1),
      completed: z.boolean(),
    })
  ),
});

export type TaskFormValues = z.infer<typeof taskFormSchema>;

// ─── Constants ───

export const PRIORITY_OPTIONS = [
  { value: "HIGH", label: "High", dot: "bg-rose-500" },
  { value: "MEDIUM", label: "Medium", dot: "bg-amber-500" },
  { value: "LOW", label: "Low", dot: "bg-blue-500" },
] as const;

export const getDefaultDueDate = () =>
  new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString().slice(0, 16);

// ─── Component Props ───

export interface TaskModalProps {
  task?: TaskType | null;
  isOpen: boolean;
  onClose: () => void;
  onSuccess?: () => void;
}

export const TaskModal: React.FC<TaskModalProps> = ({
  task,
  isOpen,
  onClose,
  onSuccess,
}) => {
  const isEditMode = Boolean(task);
  const { user } = useAuth();
  const createTask = useCreateTask();
  const { mutate: updateTask, isPending: isUpdating } = useUpdateTask();
  const { data: employeesData } = useEmployees();

  const isPending = isEditMode ? isUpdating : createTask.isPending;

  const employees = useMemo(
    () => employeesData?.employees || [],
    [employeesData?.employees]
  );

  const [activeTab, setActiveTab] = useState<"general" | "checklist">("general");
  const [attachments, setAttachments] = useState<
    { id: string; fileName: string; fileSize: number }[]
  >([]);
  const [relatedRecord, setRelatedRecord] = useState<RelatedRecord | null>(null);
  const [showWarning, setShowWarning] = useState(false);

  const form = useForm<TaskFormValues>({
    resolver: zodResolver(taskFormSchema),
    defaultValues: {
      title: "",
      description: "",
      assignedToId: user?.id || "",
      priority: "MEDIUM",
      dueDate: getDefaultDueDate(),
      checklist: [],
    },
  });

  const externalOriginalValues = useMemo(() => {
    if (!task) {
      return {
        attachments: [],
        relatedRecord: null,
      };
    }
    let initialRecord: RelatedRecord | null = null;
    if (task.relatedLead) {
      initialRecord = {
        type: "lead",
        id: task.relatedLead.id,
        label: task.relatedLead.name,
        sub: task.relatedLead.company || "",
      };
    } else if (task.relatedCustomer) {
      initialRecord = {
        type: "customer",
        id: task.relatedCustomer.id,
        label: task.relatedCustomer.name,
        sub: task.relatedCustomer.company || "",
      };
    } else if (task.relatedQuotation) {
      initialRecord = {
        type: "quotation",
        id: task.relatedQuotation.id,
        label: `#${task.relatedQuotation.quoteNumber}`,
        sub:
          task.relatedQuotation.company ||
          task.relatedQuotation.name ||
          "",
      };
    }
    return {
      attachments: task.attachments || [],
      relatedRecord: initialRecord,
    };
  }, [task]);

  const { isDirty, resetDirty } = useDirtyForm(
    form,
    form.formState.defaultValues as TaskFormValues,
    {
      externalOriginalValues,
      externalValues: { attachments, relatedRecord },
    }
  );

  const {
    fields: checklistFields,
    append: appendChecklist,
    remove: removeChecklist,
  } = useFieldArray({
    control: form.control,
    name: "checklist",
  });

  const handleAddChecklist = (title: string) => {
    appendChecklist({ id: String(Date.now()), title, completed: false });
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    const newAtts = Array.from(files).map((f) => ({
      id: `${Date.now()}-${Math.random()}`,
      fileName: f.name,
      fileSize: f.size,
    }));
    setAttachments((prev) => [...prev, ...newAtts]);
    e.target.value = "";
  };

  const handleRemoveAttachment = (id: string) => {
    setAttachments((prev) => prev.filter((a) => a.id !== id));
  };

  const resetForm = useCallback(() => {
    if (task) {
      let formattedDueDate = getDefaultDueDate();
      if (task.dueDate) {
        const parsedDate = new Date(task.dueDate);
        if (!isNaN(parsedDate.getTime())) {
          formattedDueDate = parsedDate.toISOString().slice(0, 16);
        }
      }

      form.reset({
        title: task.title || "",
        description: task.description || "",
        assignedToId: task.assignedTo?.id || user?.id || "",
        priority: (task.priority || "MEDIUM") as TaskFormValues["priority"],
        dueDate: formattedDueDate,
        checklist: task.checklist || [],
      });

      if (task.relatedLead) {
        setRelatedRecord({
          type: "lead",
          id: task.relatedLead.id,
          label: task.relatedLead.name,
          sub: task.relatedLead.company || "",
        });
      } else if (task.relatedCustomer) {
        setRelatedRecord({
          type: "customer",
          id: task.relatedCustomer.id,
          label: task.relatedCustomer.name,
          sub: task.relatedCustomer.company || "",
        });
      } else if (task.relatedQuotation) {
        setRelatedRecord({
          type: "quotation",
          id: task.relatedQuotation.id,
          label: `#${task.relatedQuotation.quoteNumber}`,
          sub:
            task.relatedQuotation.company ||
            task.relatedQuotation.name ||
            "",
        });
      } else {
        setRelatedRecord(null);
      }

      setAttachments(
        task.attachments?.map((a: TaskAttachment) => ({
          id: a.id || String(Math.random()),
          fileName: a.fileName || "file",
          fileSize: a.fileSize || 0,
        })) || []
      );
    } else {
      form.reset({
        title: "",
        description: "",
        assignedToId: user?.id || "",
        priority: "MEDIUM",
        dueDate: getDefaultDueDate(),
        checklist: [],
      });
      setRelatedRecord(null);
      setAttachments([]);
    }
    setActiveTab("general");
    resetDirty();
  }, [task, form, user?.id, resetDirty]);

  useEffect(() => {
    if (isOpen) {
      resetForm();
    }
  }, [isOpen, resetForm]);

  const handleOpenChange = (open: boolean) => {
    if (!open) {
      if (isDirty) {
        setShowWarning(true);
      } else {
        resetForm();
        onClose();
      }
    }
  };

  const onSubmit = async (values: TaskFormValues) => {
    try {
      const payload: Partial<TaskType> & {
        leadId?: string;
        customerId?: string;
        quotationId?: string;
      } = {
        title: values.title.trim(),
        description: values.description?.trim() || "",
        assignedToId: values.assignedToId,
        priority: values.priority,
        dueDate: values.dueDate
          ? new Date(values.dueDate).toISOString()
          : new Date().toISOString(),
        checklist: values.checklist,
      };

      if (relatedRecord) {
        if (relatedRecord.type === "lead") payload.leadId = relatedRecord.id;
        else if (relatedRecord.type === "customer")
          payload.customerId = relatedRecord.id;
        else if (relatedRecord.type === "quotation")
          payload.quotationId = relatedRecord.id;
      }

      if (isEditMode && task) {
        updateTask(
          { id: task.id, data: payload },
          {
            onSuccess: () => {
              resetForm();
              onSuccess?.();
              onClose();
            },
          }
        );
      } else {
        await createTask.mutateAsync(payload);
        resetForm();
        onSuccess?.();
        onClose();
      }
    } catch {
      // Error handled by mutation hook
    }
  };

  const dueDateValue = form.watch("dueDate");
  const isPastDue = dueDateValue ? new Date(dueDateValue) < new Date() : false;
  const hasErrors = Object.keys(form.formState.errors).length > 0;

  return (
    <>
      <Dialog open={isOpen} onOpenChange={handleOpenChange}>
        <DialogContent className="max-w-lg p-0 overflow-hidden flex flex-col max-h-[90vh]">
          {/* ── HEADER ── */}
          <div className="shrink-0 bg-muted/20 border-b border-border p-6 pb-4">
            <div className="flex items-center gap-3">
              <div className="size-10 rounded-xl bg-primary/10 border border-primary/20 flex items-center justify-center text-primary shrink-0">
                <AppIcon name="tasks" size={20} />
              </div>
              <div className="flex-1 min-w-0">
                <DialogTitle className="text-base font-bold text-foreground tracking-tight">
                  {isEditMode ? "Edit Task" : "New Task"}
                </DialogTitle>
                <DialogDescription className="text-xs text-muted-foreground mt-0.5">
                  {isEditMode
                    ? "Update task details and progress."
                    : "Quick-capture a task. Add details later."}
                </DialogDescription>
              </div>
            </div>
          </div>

          <Form {...form}>
            <form
              onSubmit={form.handleSubmit(onSubmit)}
              className="flex-1 flex flex-col min-h-0"
            >
              <Tabs
                value={activeTab}
                onValueChange={(val) =>
                  setActiveTab(val as "general" | "checklist")
                }
                className="flex-1 flex flex-col min-h-0"
              >
                {/* ── TAB BAR ── */}
                <TabsList className="w-full justify-start rounded-none border-b border-border bg-background px-6 h-auto p-0 gap-0 shrink-0">
                  <TabsTrigger
                    value="general"
                    className="flex items-center gap-1.5 px-4 py-2.5 text-[11px] font-bold uppercase tracking-widest border-b-2 rounded-none bg-transparent shadow-none transition-colors border-transparent text-muted-foreground hover:text-foreground data-[state=active]:border-primary data-[state=active]:text-primary data-[state=active]:bg-transparent data-[state=active]:shadow-none"
                  >
                    <AppIcon name="file" size={14} />
                    General
                  </TabsTrigger>
                  <TabsTrigger
                    value="checklist"
                    className="flex items-center gap-1.5 px-4 py-2.5 text-[11px] font-bold uppercase tracking-widest border-b-2 rounded-none bg-transparent shadow-none transition-colors border-transparent text-muted-foreground hover:text-foreground data-[state=active]:border-primary data-[state=active]:text-primary data-[state=active]:bg-transparent data-[state=active]:shadow-none"
                  >
                    <AppIcon name="tasks" size={14} />
                    Checklist
                    {checklistFields.length > 0 && (
                      <span className="ml-1 text-[9px] font-bold bg-primary/10 text-primary rounded-full size-4 inline-flex items-center justify-center">
                        {checklistFields.length}
                      </span>
                    )}
                  </TabsTrigger>
                </TabsList>

                {/* ── BODY ── */}
                <div className="flex-1 overflow-y-auto p-6">
                  {/* ===== GENERAL TAB ===== */}
                  <TabsContent
                    value="general"
                    className="mt-0 space-y-4 focus-visible:outline-none"
                  >
                    {/* Title */}
                    <FormField
                      control={form.control}
                      name="title"
                      render={({ field }) => (
                        <FormItem className="space-y-1.5">
                          <Label className="text-[11px] font-bold text-muted-foreground uppercase tracking-widest">
                            Task Title <span className="text-destructive">*</span>
                          </Label>
                          <FormControl>
                            <Input
                              placeholder="Enter task title"
                              className="h-10 text-sm font-medium"
                              autoFocus
                              {...field}
                            />
                          </FormControl>
                          <FormMessage className="text-xs" />
                        </FormItem>
                      )}
                    />

                    {/* Description */}
                    <FormField
                      control={form.control}
                      name="description"
                      render={({ field }) => (
                        <FormItem className="space-y-1.5">
                          <Label className="text-[11px] font-bold text-muted-foreground uppercase tracking-widest">
                            Description
                          </Label>
                          <FormControl>
                            <Textarea
                              placeholder={
                                isEditMode
                                  ? "Enter task description or context..."
                                  : "Enter task notes or context..."
                              }
                              className="resize-none min-h-[72px] text-sm"
                              {...field}
                            />
                          </FormControl>
                        </FormItem>
                      )}
                    />

                    {/* Assign To + Priority — side by side */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      <FormField
                        control={form.control}
                        name="assignedToId"
                        render={({ field }) => (
                          <FormItem className="space-y-1.5">
                            <Label className="text-[11px] font-bold text-muted-foreground uppercase tracking-widest">
                              Assign To <span className="text-destructive">*</span>
                            </Label>
                            <Select
                              onValueChange={field.onChange}
                              value={field.value}
                            >
                              <FormControl>
                                <SelectTrigger className="h-10 w-full text-sm font-medium">
                                  <SelectValue placeholder="Select..." />
                                </SelectTrigger>
                              </FormControl>
                              <SelectContent>
                                {employees.map(
                                  (emp: {
                                    id?: string;
                                    userId?: string;
                                    name: string;
                                  }) => (
                                    <SelectItem
                                      key={emp.id}
                                      value={emp.id || emp.userId || ""}
                                    >
                                      {emp.name}
                                    </SelectItem>
                                  )
                                )}
                                {employees.length === 0 && user?.id && (
                                  <SelectItem value={user.id}>
                                    {user.name || "Me"}
                                  </SelectItem>
                                )}
                              </SelectContent>
                            </Select>
                            <FormMessage className="text-xs" />
                          </FormItem>
                        )}
                      />

                      <FormField
                        control={form.control}
                        name="priority"
                        render={({ field }) => (
                          <FormItem className="space-y-1.5">
                            <Label className="text-[11px] font-bold text-muted-foreground uppercase tracking-widest">
                              Priority
                            </Label>
                            <Select
                              onValueChange={field.onChange}
                              value={field.value}
                            >
                              <FormControl>
                                <SelectTrigger className="h-10 w-full text-sm font-medium">
                                  <SelectValue placeholder="Select priority" />
                                </SelectTrigger>
                              </FormControl>
                              <SelectContent>
                                {PRIORITY_OPTIONS.map((p) => (
                                  <SelectItem key={p.value} value={p.value}>
                                    {p.label}
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                          </FormItem>
                        )}
                      />
                    </div>

                    {/* Due Date */}
                    <FormField
                      control={form.control}
                      name="dueDate"
                      render={({ field }) => (
                        <FormItem className="space-y-1.5">
                          <Label className="text-[11px] font-bold text-muted-foreground uppercase tracking-widest">
                            Due Date <span className="text-destructive">*</span>
                          </Label>
                          <FormControl>
                            <Input
                              type="datetime-local"
                              className="h-10 text-sm"
                              {...field}
                            />
                          </FormControl>
                          {isPastDue && (
                            <p className="text-[11px] text-amber-600 dark:text-amber-400 flex items-center gap-1 font-semibold">
                              <AlertCircle className="size-3" />
                              This date is in the past
                            </p>
                          )}
                          <FormMessage className="text-xs" />
                        </FormItem>
                      )}
                    />

                    {/* Related Record */}
                    <TaskRelatedRecordPicker
                      relatedRecord={relatedRecord}
                      onSelectRecord={setRelatedRecord}
                    />
                  </TabsContent>

                  {/* ===== CHECKLIST TAB ===== */}
                  <TabsContent
                    value="checklist"
                    className="mt-0 focus-visible:outline-none"
                  >
                    <TaskChecklistTab
                      checklistFields={checklistFields}
                      onAddChecklist={handleAddChecklist}
                      onRemoveChecklist={removeChecklist}
                      attachments={attachments}
                      onFileUpload={handleFileUpload}
                      onRemoveAttachment={handleRemoveAttachment}
                    />
                  </TabsContent>
                </div>
              </Tabs>

              {/* ── FOOTER ── */}
              <div className="shrink-0 px-6 py-4 border-t border-border bg-muted/10 flex items-center justify-between">
                <div>
                  {hasErrors && (
                    <p className="text-xs text-destructive font-semibold flex items-center gap-1">
                      <AlertCircle className="size-3.5" />
                      Check required fields
                    </p>
                  )}
                </div>
                <div className="flex items-center gap-2">
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={() => handleOpenChange(false)}
                    disabled={isPending}
                    className="h-9 px-4 text-xs font-semibold"
                  >
                    <AppIcon name="close" size={15} className="mr-1.5" />
                    Cancel
                  </Button>
                  <FormSubmitButton
                    isDirty={isDirty}
                    isPending={isPending}
                    size="sm"
                    className="h-9 px-6 text-xs font-bold rounded-lg shadow-sm min-w-28"
                    loadingText={isEditMode ? "Saving..." : "Creating..."}
                  >
                    {isEditMode ? "Save Changes" : "Create Task"}
                  </FormSubmitButton>
                </div>
              </div>
            </form>
          </Form>
        </DialogContent>
      </Dialog>
      <UnsavedWarning
        open={showWarning}
        onOpenChange={setShowWarning}
        onConfirm={() => {
          setShowWarning(false);
          resetForm();
          onClose();
        }}
        onCancel={() => setShowWarning(false)}
      />
    </>
  );
};

import { tool } from 'ai';
import { z } from 'zod';

export interface McpUserContext {
  authToken: string;
  userId?: string;
  tenantId?: string;
  role?: string;
  correlationId?: string;
}

const CRM_API_BASE_URL =
  process.env.CRM_API_BASE_URL ||
  process.env.NEXT_PUBLIC_API_URL ||
  'http://localhost:4000/api';

/**
 * Sanitizes headers and scrubs sensitive tokens from error messages.
 */
function scrubError(text: string): string {
  if (!text) return 'An unexpected error occurred.';
  return text
    .replace(/eyJ[a-zA-Z0-9_-]{10,}\.[a-zA-Z0-9_-]{10,}\.[a-zA-Z0-9_-]*/g, '[REDACTED_TOKEN]')
    .replace(/PrismaClientKnownRequestError/i, 'DatabaseError')
    .replace(/SELECT\s+.+\s+FROM/gi, '[QUERY_REDACTED]');
}

/**
 * Dispatches an authenticated HTTP request to the ClixProCRM API gateway on behalf of the user.
 */
async function callCrmApi(
  context: McpUserContext,
  endpoint: string,
  method = 'GET',
  body?: unknown,
  query?: Record<string, string | number | boolean | undefined | null>
): Promise<any> {
  const cleanBase = CRM_API_BASE_URL.replace(/\/+$/, '');
  const cleanPath = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
  const url = new URL(`${cleanBase}${cleanPath}`);

  if (query) {
    for (const [key, value] of Object.entries(query)) {
      if (value !== undefined && value !== null) {
        url.searchParams.set(key, String(value));
      }
    }
  }

  const headers: Record<string, string> = {
    Accept: 'application/json',
    'Content-Type': 'application/json',
  };

  if (context.authToken) {
    headers['Authorization'] = `Bearer ${context.authToken}`;
  }
  if (context.correlationId) {
    headers['X-Correlation-ID'] = context.correlationId;
    headers['X-Request-ID'] = context.correlationId;
  }

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 10000);

  try {
    const res = await fetch(url.toString(), {
      method,
      headers,
      body: body ? JSON.stringify(body) : undefined,
      signal: controller.signal,
    });
    clearTimeout(timeoutId);

    if (!res.ok) {
      let errorMsg = `CRM API responded with status ${res.status}`;
      try {
        const errorData = await res.json();
        if (errorData?.message) {
          errorMsg = Array.isArray(errorData.message)
            ? errorData.message.join(', ')
            : String(errorData.message);
        }
      } catch {
        // Fall back to status text
      }

      if (res.status === 401) {
        return { error: 'Authentication expired or invalid. Please sign in again.' };
      }
      if (res.status === 403) {
        return { error: 'Permission denied: Your role does not allow this operation.' };
      }
      if (res.status === 404) {
        return { error: 'Resource not found in CRM.' };
      }
      if (res.status === 429) {
        return { error: 'Rate limit exceeded. Please wait a moment before trying again.' };
      }
      if (res.status >= 500) {
        return { error: 'CRM service is temporarily unavailable. Please try again shortly.' };
      }

      return { error: scrubError(errorMsg) };
    }

    const data = await res.json();
    return data?.data !== undefined ? data.data : data;
  } catch (err: any) {
    clearTimeout(timeoutId);
    if (err.name === 'AbortError') {
      return { error: 'Request to CRM service timed out. Please try again.' };
    }
    return { error: 'Could not connect to CRM backend service. Please check your network connection.' };
  }
}

/**
 * Builds the authorized MCP tools for the current authenticated user context.
 */
export function getMcpTools(context: McpUserContext) {
  return {
    // 1. get_current_user (Read)
    get_current_user: tool({
      description: "Get the authenticated user's permitted CRM profile.",
      inputSchema: z.object({}),
      execute: async () => {
        const data = await callCrmApi(context, '/auth/me', 'GET');
        return data;
      },
    }),

    // 2. list_leads (Read)
    list_leads: tool({
      description: 'List leads accessible to the user with optional filters.',
      inputSchema: z.object({
        search: z.string().max(100).optional().describe('Search by lead name, email, or company'),
        status: z.string().max(50).optional().describe('Filter by lead stage/status (e.g. NEW, QUALIFIED, WON, LOST)'),
        page: z.number().int().min(1).default(1).optional().describe('Page number'),
        limit: z.number().int().min(1).max(50).default(10).optional().describe('Number of leads to retrieve'),
        sort: z.string().max(50).optional().describe('Sort order field'),
      }),
      execute: async (args: { search?: string; status?: string; page?: number; limit?: number; sort?: string }) => {
        const data = await callCrmApi(context, '/crm/leads', 'GET', undefined, {
          search: args.search,
          status: args.status,
          page: args.page || 1,
          limit: Math.min(Math.max(1, args.limit || 10), 50),
          sort: args.sort,
        });
        return data;
      },
    }),

    // 3. get_lead (Read)
    get_lead: tool({
      description: 'Get details of a single lead by its unique ID.',
      inputSchema: z.object({
        id: z.string().min(1).max(100).describe('The unique ID of the lead'),
      }),
      execute: async ({ id }: { id: string }) => {
        const data = await callCrmApi(context, `/crm/leads/${encodeURIComponent(id)}`, 'GET');
        return data;
      },
    }),

    // 4. create_lead (Controlled Write)
    create_lead: tool({
      description:
        'Create a new lead. Explicit confirmation (confirmed === true) is required before executing the creation.',
      inputSchema: z.object({
        name: z.string().min(1).max(200).describe('Lead contact full name'),
        email: z.string().email().max(200).describe('Lead email address'),
        company: z.string().max(200).optional().describe('Company or organization'),
        phone: z.string().max(50).optional().describe('Phone number'),
        source: z.string().max(100).optional().describe('Lead source'),
        stage: z.enum(['NEW', 'CONTACTED', 'QUALIFIED', 'PROPOSAL', 'NEGOTIATION', 'WON', 'LOST']).optional(),
        priority: z.enum(['LOW', 'MEDIUM', 'HIGH', 'URGENT']).optional(),
        value: z.number().min(0).optional().describe('Estimated budget or deal value'),
        expectedCloseDate: z.string().max(50).optional().describe('Target close date (YYYY-MM-DD)'),
        tags: z.array(z.string().max(50)).max(20).optional().describe('Tags'),
        confirmed: z
          .boolean()
          .describe('Explicit confirmation must be true to authorize CRM lead creation'),
      }),
      execute: async (args: any) => {
        if (args.confirmed !== true) {
          return {
            confirmationRequired: true,
            message: 'Confirmation is required before creating this lead. Please confirm details with the user.',
            proposedData: {
              name: args.name,
              email: args.email,
              company: args.company,
              value: args.value,
              stage: args.stage,
            },
          };
        }
        const { confirmed: _confirmed, ...payload } = args;
        const data = await callCrmApi(context, '/crm/leads', 'POST', payload);
        return data;
      },
    }),

    // 5. update_lead (Controlled Write)
    update_lead: tool({
      description:
        'Update an existing lead. Explicit confirmation (confirmed === true) is required before updating.',
      inputSchema: z.object({
        id: z.string().min(1).max(100).describe('The unique ID of the lead to update'),
        name: z.string().min(1).max(200).optional(),
        company: z.string().max(200).optional(),
        email: z.string().email().max(200).optional(),
        phone: z.string().max(50).optional(),
        stage: z.enum(['NEW', 'CONTACTED', 'QUALIFIED', 'PROPOSAL', 'NEGOTIATION', 'WON', 'LOST']).optional(),
        priority: z.enum(['LOW', 'MEDIUM', 'HIGH', 'URGENT']).optional(),
        value: z.number().min(0).optional(),
        expectedCloseDate: z.string().max(50).optional(),
        notes: z.string().max(2000).optional(),
        confirmed: z
          .boolean()
          .describe('Explicit confirmation must be true to authorize CRM lead update'),
      }),
      execute: async (args: any) => {
        if (args.confirmed !== true) {
          return {
            confirmationRequired: true,
            message: 'Confirmation is required before modifying this lead. Please confirm with the user.',
            leadId: args.id,
          };
        }
        const { id, confirmed: _confirmed, ...payload } = args;
        const data = await callCrmApi(context, `/crm/leads/${encodeURIComponent(id)}`, 'PUT', payload);
        return data;
      },
    }),

    // 6. list_customers (Read)
    list_customers: tool({
      description: 'List customers accessible to the user with optional filters.',
      inputSchema: z.object({
        search: z.string().max(100).optional().describe('Search by customer name, company, or email'),
        page: z.number().int().min(1).default(1).optional().describe('Page number'),
        limit: z.number().int().min(1).max(50).default(10).optional().describe('Max customers to retrieve'),
        sort: z.string().max(50).optional().describe('Sort order field'),
      }),
      execute: async (args: { search?: string; page?: number; limit?: number; sort?: string }) => {
        const data = await callCrmApi(context, '/crm/customers', 'GET', undefined, {
          search: args.search,
          page: args.page || 1,
          limit: Math.min(Math.max(1, args.limit || 10), 50),
          sort: args.sort,
        });
        return data;
      },
    }),

    // 7. get_customer (Read)
    get_customer: tool({
      description: 'Get details of a single customer by ID.',
      inputSchema: z.object({
        id: z.string().min(1).max(100).describe('The unique ID of the customer'),
      }),
      execute: async ({ id }: { id: string }) => {
        const data = await callCrmApi(context, `/crm/customers/${encodeURIComponent(id)}`, 'GET');
        return data;
      },
    }),

    // 8. create_customer (Controlled Write)
    create_customer: tool({
      description:
        'Create a new customer account. Explicit confirmation (confirmed === true) is required before creation.',
      inputSchema: z.object({
        name: z.string().min(1).max(200).describe('Customer contact name'),
        company: z.string().min(1).max(200).describe('Customer company name'),
        email: z.string().email().max(200).optional().describe('Email address'),
        revenue: z.number().min(0).optional().describe('Annual or estimated revenue'),
        status: z.enum(['ACTIVE', 'INACTIVE', 'PENDING', 'VIP']).optional(),
        confirmed: z
          .boolean()
          .describe('Explicit confirmation must be true to authorize CRM customer creation'),
      }),
      execute: async (args: any) => {
        if (args.confirmed !== true) {
          return {
            confirmationRequired: true,
            message: 'Confirmation is required before creating this customer. Please confirm with the user.',
            proposedData: {
              name: args.name,
              company: args.company,
              email: args.email,
            },
          };
        }
        const { confirmed: _confirmed, ...payload } = args;
        const data = await callCrmApi(context, '/crm/customers', 'POST', payload);
        return data;
      },
    }),

    // 9. update_customer (Controlled Write)
    update_customer: tool({
      description:
        'Update an existing customer account. Explicit confirmation (confirmed === true) is required before updating.',
      inputSchema: z.object({
        id: z.string().min(1).max(100).describe('The unique ID of the customer to update'),
        name: z.string().min(1).max(200).optional(),
        company: z.string().max(200).optional(),
        email: z.string().email().max(200).optional(),
        revenue: z.number().min(0).optional(),
        status: z.enum(['ACTIVE', 'INACTIVE', 'PENDING', 'VIP']).optional(),
        confirmed: z
          .boolean()
          .describe('Explicit confirmation must be true to authorize CRM customer update'),
      }),
      execute: async (args: any) => {
